{"path": "server.js", "content": "import express from 'express';
import cors from 'cors';
import { PGlite } from '@electric-sql/pglite';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const PORT = process.env.PORT || 3000;

const app = express();
app.use(cors());
app.use(express.json());

const db = new PGlite(path.join(__dirname, 'pgdata'));

await db.query(`
  CREATE TABLE IF NOT EXISTS events (
    id SERIAL PRIMARY KEY,
    title TEXT NOT NULL,
    start_at TIMESTAMP NOT NULL,
    end_at TIMESTAMP NOT NULL,
    CONSTRAINT valid_event_time CHECK (end_at > start_at)
  );
`);

function isValidDate(value) {
  const d = new Date(value);
  return value && !Number.isNaN(d.getTime());
}

function validateEventPayload(body) {
  const title = typeof body.title === 'string' ? body.title.trim() : '';
  const start_at = body.start_at ?? body.start;
  const end_at = body.end_at ?? body.end;
  if (!title) return { error: 'Title is required' };
  if (!isValidDate(start_at) || !isValidDate(end_at)) return { error: 'Valid start_at and end_at are required' };
  if (new Date(end_at).getTime() <= new Date(start_at).getTime()) return { error: 'end_at must be after start_at' };
  return { title, start_at: new Date(start_at).toISOString(), end_at: new Date(end_at).toISOString() };
}

function rowToEvent(row) {
  return {
    id: row.id,
    title: row.title,
    start_at: new Date(row.start_at).toISOString(),
    end_at: new Date(row.end_at).toISOString(),
  };
}

app.get('/api/health', (req, res) => res.json({ ok: true }));

app.get('/api/events', async (req, res) => {
  try {
    const { start, end } = req.query;
    if (!isValidDate(start) || !isValidDate(end) || new Date(end) <= new Date(start)) {
      return res.status(400).json({ error: 'Valid start and end query parameters are required' });
    }
    const result = await db.query(
      `SELECT id, title, start_at, end_at
       FROM events
       WHERE start_at < $2::timestamp AND end_at > $1::timestamp
       ORDER BY start_at ASC, end_at ASC, id ASC`,
      [new Date(start).toISOString(), new Date(end).toISOString()]
    );
    res.json(result.rows.map(rowToEvent));
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to fetch events' });
  }
});

app.post('/api/events', async (req, res) => {
  try {
    const valid = validateEventPayload(req.body || {});
    if (valid.error) return res.status(400).json({ error: valid.error });
    const result = await db.query(
      `INSERT INTO events (title, start_at, end_at)
       VALUES ($1, $2::timestamp, $3::timestamp)
       RETURNING id, title, start_at, end_at`,
      [valid.title, valid.start_at, valid.end_at]
    );
    res.status(201).json(rowToEvent(result.rows[0]));
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to create event' });
  }
});

app.put('/api/events/:id', async (req, res) => {
  try {
    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) return res.status(400).json({ error: 'Invalid id' });
    const valid = validateEventPayload(req.body || {});
    if (valid.error) return res.status(400).json({ error: valid.error });
    const result = await db.query(
      `UPDATE events
       SET title = $1, start_at = $2::timestamp, end_at = $3::timestamp
       WHERE id = $4
       RETURNING id, title, start_at, end_at`,
      [valid.title, valid.start_at, valid.end_at, id]
    );
    if (result.rows.length === 0) return res.status(404).json({ error: 'Event not found' });
    res.json(rowToEvent(result.rows[0]));
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to update event' });
  }
});

app.delete('/api/events/:id', async (req, res) => {
  try {
    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) return res.status(400).json({ error: 'Invalid id' });
    const result = await db.query('DELETE FROM events WHERE id = $1 RETURNING id', [id]);
    if (result.rows.length === 0) return res.status(404).json({ error: 'Event not found' });
    res.status(204).end();
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to delete event' });
  }
});

app.listen(PORT, () => {
  console.log(`Calendar API listening on http://localhost:${PORT}`);
});
"}

{"path": "src/main.js", "content": "import './styles.css';

const API_BASE = 'http://localhost:3000/api';
const HOUR_HEIGHT = 64;
const DAY_HEIGHT = HOUR_HEIGHT * 24;
const SNAP_MINUTES = 15;
const DAY_NAMES = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

const app = document.querySelector('#app');
app.innerHTML = `
  <header class="toolbar">
    <div class="brand">
      <h1>Week Calendar</h1>
      <p>Minute-precision week view</p>
    </div>
    <nav class="nav-actions">
      <button id="prevWeek" type="button">← Previous</button>
      <button id="today" type="button">Today</button>
      <button id="nextWeek" type="button">Next →</button>
    </nav>
    <div id="rangeLabel" class="range-label"></div>
  </header>
  <main class="calendar-shell">
    <div class="calendar-header">
      <div class="time-gutter header-gutter"></div>
      <div id="dayHeaders" class="day-headers"></div>
    </div>
    <div class="calendar-scroll">
      <div class="time-gutter" id="timeGutter"></div>
      <div id="weekGrid" class="week-grid"></div>
    </div>
  </main>

  <div id="modalBackdrop" class="modal-backdrop hidden">
    <form id="eventForm" class="event-form">
      <h2 id="formTitle">New event</h2>
      <label>
        Title
        <input id="eventTitle" name="title" type="text" required maxlength="120" />
      </label>
      <div class="form-row">
        <label>
          Start
          <input id="eventStart" name="start" type="datetime-local" required />
        </label>
        <label>
          End
          <input id="eventEnd" name="end" type="datetime-local" required />
        </label>
      </div>
      <p id="formError" class="form-error" role="alert"></p>
      <div class="form-actions">
        <button id="deleteEvent" class="danger hidden" type="button">Delete</button>
        <span class="spacer"></span>
        <button id="cancelForm" type="button">Cancel</button>
        <button class="primary" type="submit">Save</button>
      </div>
    </form>
  </div>
`;

let weekStart = startOfWeek(new Date());
let events = [];
let editingEvent = null;
let dragState = null;

const els = {
  prevWeek: document.querySelector('#prevWeek'),
  today: document.querySelector('#today'),
  nextWeek: document.querySelector('#nextWeek'),
  rangeLabel: document.querySelector('#rangeLabel'),
  dayHeaders: document.querySelector('#dayHeaders'),
  timeGutter: document.querySelector('#timeGutter'),
  weekGrid: document.querySelector('#weekGrid'),
  modalBackdrop: document.querySelector('#modalBackdrop'),
  eventForm: document.querySelector('#eventForm'),
  formTitle: document.querySelector('#formTitle'),
  eventTitle: document.querySelector('#eventTitle'),
  eventStart: document.querySelector('#eventStart'),
  eventEnd: document.querySelector('#eventEnd'),
  formError: document.querySelector('#formError'),
  deleteEvent: document.querySelector('#deleteEvent'),
  cancelForm: document.querySelector('#cancelForm'),
};

initStaticGrid();
attachHandlers();
loadWeek();

function initStaticGrid() {
  els.timeGutter.innerHTML = '';
  for (let h = 0; h <= 24; h++) {
    const label = document.createElement('div');
    label.className = 'time-label';
    label.style.top = `${h * HOUR_HEIGHT}px`;
    label.textContent = `${String(h).padStart(2, '0')}:00`;
    els.timeGutter.appendChild(label);
  }
}

function attachHandlers() {
  els.prevWeek.addEventListener('click', () => changeWeek(-7));
  els.nextWeek.addEventListener('click', () => changeWeek(7));
  els.today.addEventListener('click', () => { weekStart = startOfWeek(new Date()); loadWeek(); });
  els.cancelForm.addEventListener('click', closeModal);
  els.modalBackdrop.addEventListener('mousedown', (e) => { if (e.target === els.modalBackdrop) closeModal(); });
  els.eventForm.addEventListener('submit', saveEvent);
  els.deleteEvent.addEventListener('click', deleteCurrentEvent);
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') closeModal(); });
}

async function loadWeek() {
  renderHeaders();
  try {
    const start = weekStart.toISOString();
    const end = addDays(weekStart, 7).toISOString();
    const res = await fetch(`${API_BASE}/events?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}`);
    if (!res.ok) throw new Error('Failed to load events');
    events = await res.json();
    renderWeekGrid();
  } catch (err) {
    console.error(err);
    events = [];
    renderWeekGrid('Could not load events. Is the API server running?');
  }
}

function renderHeaders() {
  const end = addDays(weekStart, 6);
  els.rangeLabel.textContent = `${formatMonthDay(weekStart)} – ${formatMonthDay(end)} ${end.getFullYear()}`;
  els.dayHeaders.innerHTML = '';
  const todayKey = dateKey(new Date());
  for (let i = 0; i < 7; i++) {
    const d = addDays(weekStart, i);
    const header = document.createElement('div');
    header.className = `day-header ${dateKey(d) === todayKey ? 'today' : ''}`;
    header.innerHTML = `<span>${DAY_NAMES[i]}</span><strong>${d.getDate()}</strong>`;
    els.dayHeaders.appendChild(header);
  }
}

function renderWeekGrid(errorMessage = '') {
  els.weekGrid.innerHTML = '';
  els.weekGrid.style.height = `${DAY_HEIGHT}px`;
  for (let i = 0; i < 7; i++) {
    const day = addDays(weekStart, i);
    const col = document.createElement('section');
    col.className = `day-column ${dateKey(day) === dateKey(new Date()) ? 'today' : ''}`;
    col.dataset.dayIndex = String(i);
    col.style.height = `${DAY_HEIGHT}px`;
    for (let h = 0; h <= 24; h++) {
      const line = document.createElement('div');
      line.className = h === 24 ? 'hour-line last' : 'hour-line';
      line.style.top = `${h * HOUR_HEIGHT}px`;
      col.appendChild(line);
    }
    setupSelectionHandlers(col, day);
    els.weekGrid.appendChild(col);
  }

  if (errorMessage) {
    const msg = document.createElement('div');
    msg.className = 'grid-message';
    msg.textContent = errorMessage;
    els.weekGrid.appendChild(msg);
    return;
  }

  const byDay = splitAndGroupEventsByDay(events);
  byDay.forEach((dayEvents, dayIndex) => {
    const col = els.weekGrid.querySelector(`[data-day-index="${dayIndex}"]`);
    layoutDayEvents(dayEvents).forEach((item) => {
      const el = document.createElement('button');
      el.type = 'button';
      el.className = 'event-block';
      el.style.top = `${item.top}px`;
      el.style.height = `${item.height}px`;
      el.style.left = `calc(${item.leftPct}% + 3px)`;
      el.style.width = `calc(${item.widthPct}% - 6px)`;
      el.innerHTML = `<strong title="${escapeHtml(item.event.title)}">${escapeHtml(item.event.title)}</strong><span>${formatTime(item.visibleStart)}–${formatTime(item.visibleEnd)}</span>`;
      el.addEventListener('click', (e) => {
        e.stopPropagation();
        openEditForm(item.event);
      });
      col.appendChild(el);
    });
  });
}

function splitAndGroupEventsByDay(rawEvents) {
  const days = Array.from({ length: 7 }, () => []);
  const weekEnd = addDays(weekStart, 7);
  rawEvents.forEach((event) => {
    const originalStart = new Date(event.start_at);
    const originalEnd = new Date(event.end_at);
    for (let i = 0; i < 7; i++) {
      const dayStart = addDays(weekStart, i);
      const dayEnd = addDays(dayStart, 1);
      const visibleStart = maxDate(originalStart, dayStart);
      const visibleEnd = minDate(originalEnd, dayEnd, weekEnd);
      if (visibleStart < visibleEnd) {
        days[i].push({ event, visibleStart, visibleEnd });
      }
    }
  });
  return days;
}

function layoutDayEvents(dayEvents) {
  const sorted = [...dayEvents].sort((a, b) => a.visibleStart - b.visibleStart || a.visibleEnd - b.visibleEnd || a.event.id - b.event.id);
  const clusters = [];
  let current = [];
  let clusterEnd = null;

  sorted.forEach((item) => {
    if (current.length === 0 || item.visibleStart < clusterEnd) {
      current.push(item);
      clusterEnd = clusterEnd ? maxDate(clusterEnd, item.visibleEnd) : item.visibleEnd;
    } else {
      clusters.push(current);
      current = [item];
      clusterEnd = item.visibleEnd;
    }
  });
  if (current.length) clusters.push(current);

  const laidOut = [];
  clusters.forEach((cluster) => {
    const columns = [];
    const placements = [];
    cluster.forEach((item) => {
      let colIndex = columns.findIndex((end) => end <= item.visibleStart);
      if (colIndex === -1) {
        colIndex = columns.length;
        columns.push(item.visibleEnd);
      } else {
        columns[colIndex] = item.visibleEnd;
      }
      placements.push({ item, colIndex });
    });
    const colCount = Math.max(columns.length, 1);
    placements.forEach(({ item, colIndex }) => {
      const startMin = minutesSinceMidnight(item.visibleStart);
      const endMin = minutesSinceMidnight(item.visibleEnd);
      laidOut.push({
        ...item,
        top: (startMin / 60) * HOUR_HEIGHT,
        height: Math.max(1, ((endMin - startMin) / 60) * HOUR_HEIGHT),
        leftPct: (colIndex / colCount) * 100,
        widthPct: 100 / colCount,
      });
    });
  });
  return laidOut;
}

function setupSelectionHandlers(col, day) {
  col.addEventListener('mousedown', (e) => {
    if (e.button !== 0 || e.target.closest('.event-block')) return;
    const rect = col.getBoundingClientRect();
    const startY = clamp(e.clientY - rect.top, 0, DAY_HEIGHT);
    const preview = document.createElement('div');
    preview.className = 'selection-preview';
    preview.style.top = `${startY}px`;
    preview.style.height = '1px';
    col.appendChild(preview);
    dragState = { col, day, rect, startY, currentY: startY, preview, moved: false };
    e.preventDefault();
  });

  col.addEventListener('click', (e) => {
    if (e.target.closest('.event-block') || dragState) return;
    const rect = col.getBoundingClientRect();
    const y = clamp(e.clientY - rect.top, 0, DAY_HEIGHT - 1);
    const startMin = snapMinutes((y / DAY_HEIGHT) * 1440);
    openCreateForm(dateAtMinutes(day, startMin), dateAtMinutes(day, Math.min(startMin + 60, 1440)));
  });
}

document.addEventListener('mousemove', (e) => {
  if (!dragState) return;
  const y = clamp(e.clientY - dragState.rect.top, 0, DAY_HEIGHT);
  dragState.currentY = y;
  if (Math.abs(y - dragState.startY) > 3) dragState.moved = true;
  const top = Math.min(dragState.startY, y);
  const height = Math.max(1, Math.abs(y - dragState.startY));
  dragState.preview.style.top = `${top}px`;
  dragState.preview.style.height = `${height}px`;
});

document.addEventListener('mouseup', () => {
  if (!dragState) return;
  const state = dragState;
  dragState = null;
  state.preview.remove();
  if (!state.moved) return;
  let a = snapMinutes((Math.min(state.startY, state.currentY) / DAY_HEIGHT) * 1440);
  let b = snapMinutes((Math.max(state.startY, state.currentY) / DAY_HEIGHT) * 1440);
  if (b <= a) b = Math.min(a + SNAP_MINUTES, 1440);
  openCreateForm(dateAtMinutes(state.day, a), dateAtMinutes(state.day, b));
});

function openCreateForm(start, end) {
  editingEvent = null;
  els.formTitle.textContent = 'New event';
  els.eventTitle.value = '';
  els.eventStart.value = toDatetimeLocalValue(start);
  els.eventEnd.value = toDatetimeLocalValue(end);
  els.deleteEvent.classList.add('hidden');
  els.formError.textContent = '';
  els.modalBackdrop.classList.remove('hidden');
  els.eventTitle.focus();
}

function openEditForm(event) {
  editingEvent = event;
  els.formTitle.textContent = 'Edit event';
  els.eventTitle.value = event.title;
  els.eventStart.value = toDatetimeLocalValue(new Date(event.start_at));
  els.eventEnd.value = toDatetimeLocalValue(new Date(event.end_at));
  els.deleteEvent.classList.remove('hidden');
  els.formError.textContent = '';
  els.modalBackdrop.classList.remove('hidden');
  els.eventTitle.focus();
}

function closeModal() {
  els.modalBackdrop.classList.add('hidden');
  editingEvent = null;
}

async function saveEvent(e) {
  e.preventDefault();
  els.formError.textContent = '';
  const payload = {
    title: els.eventTitle.value.trim(),
    start_at: new Date(els.eventStart.value).toISOString(),
    end_at: new Date(els.eventEnd.value).toISOString(),
  };
  if (!payload.title) return (els.formError.textContent = 'Title is required.');
  if (new Date(payload.end_at) <= new Date(payload.start_at)) return (els.formError.textContent = 'End must be after start.');
  try {
    const url = editingEvent ? `${API_BASE}/events/${editingEvent.id}` : `${API_BASE}/events`;
    const method = editingEvent ? 'PUT' : 'POST';
    const res = await fetch(url, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      throw new Error(err.error || 'Save failed');
    }
    closeModal();
    await loadWeek();
  } catch (err) {
    els.formError.textContent = err.message;
  }
}

async function deleteCurrentEvent() {
  if (!editingEvent) return;
  if (!confirm('Delete this event?')) return;
  try {
    const res = await fetch(`${API_BASE}/events/${editingEvent.id}`, { method: 'DELETE' });
    if (!res.ok) throw new Error('Delete failed');
    closeModal();
    await loadWeek();
  } catch (err) {
    els.formError.textContent = err.message;
  }
}

function changeWeek(days) {
  weekStart = addDays(weekStart, days);
  loadWeek();
}

function startOfWeek(date) {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  const day = d.getDay();
  const diff = (day + 6) % 7;
  d.setDate(d.getDate() - diff);
  return d;
}

function addDays(date, days) {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

function dateAtMinutes(day, minutes) {
  const d = new Date(day);
  d.setHours(0, 0, 0, 0);
  d.setMinutes(minutes);
  return d;
}

function minutesSinceMidnight(date) {
  return date.getHours() * 60 + date.getMinutes() + date.getSeconds() / 60 + date.getMilliseconds() / 60000;
}

function snapMinutes(minutes) {
  return clamp(Math.round(minutes / SNAP_MINUTES) * SNAP_MINUTES, 0, 1440);
}

function toDatetimeLocalValue(date) {
  const d = new Date(date);
  const pad = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function formatTime(date) {
  return `${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
}

function formatMonthDay(date) {
  return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
}

function dateKey(date) {
  const d = new Date(date);
  return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
}

function minDate(...dates) {
  return new Date(Math.min(...dates.map((d) => new Date(d).getTime())));
}

function maxDate(...dates) {
  return new Date(Math.max(...dates.map((d) => new Date(d).getTime())));
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function escapeHtml(value) {
  return String(value).replace(/[&<>'"]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[ch]));
}
"}

{"path": "src/styles.css", "content": ":root {
  --gutter-width: 72px;
  --header-height: 72px;
  --hour-height: 64px;
  --grid-border: #d8dee8;
  --grid-soft: #eef2f7;
  --text: #152238;
  --muted: #687589;
  --blue: #2563eb;
  --blue-dark: #1749b7;
  --today: #eff6ff;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--text);
  background: #f7f9fc;
}

* { box-sizing: border-box; }
html, body, #app { margin: 0; min-height: 100%; }
button, input { font: inherit; }

.toolbar {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 18px 24px;
  background: #ffffff;
  border-bottom: 1px solid var(--grid-border);
  position: sticky;
  top: 0;
  z-index: 20;
}

.brand { margin-right: auto; }
.brand h1 { margin: 0; font-size: 22px; line-height: 1.1; }
.brand p { margin: 3px 0 0; color: var(--muted); font-size: 13px; }
.nav-actions { display: flex; gap: 8px; }
.nav-actions button,
.form-actions button {
  border: 1px solid var(--grid-border);
  background: #fff;
  border-radius: 9px;
  padding: 8px 12px;
  cursor: pointer;
  color: var(--text);
}
.nav-actions button:hover,
.form-actions button:hover { background: #f2f5f9; }
.range-label { min-width: 190px; text-align: right; color: var(--muted); font-weight: 600; }

.calendar-shell {
  margin: 18px 24px 28px;
  border: 1px solid var(--grid-border);
  border-radius: 14px;
  overflow: hidden;
  background: white;
  box-shadow: 0 12px 32px rgba(21, 34, 56, 0.08);
}

.calendar-header {
  display: grid;
  grid-template-columns: var(--gutter-width) 1fr;
  height: var(--header-height);
  border-bottom: 1px solid var(--grid-border);
  background: #fff;
  position: sticky;
  top: 79px;
  z-index: 10;
}
.header-gutter { border-right: 1px solid var(--grid-border); }
.day-headers,
.week-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(120px, 1fr));
}
.day-header {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 4px;
  border-right: 1px solid var(--grid-border);
  color: var(--muted);
}
.day-header:last-child { border-right: 0; }
.day-header strong {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  font-size: 18px;
  color: var(--text);
}
.day-header.today { background: var(--today); color: var(--blue); }
.day-header.today strong { background: var(--blue); color: white; }

.calendar-scroll {
  display: grid;
  grid-template-columns: var(--gutter-width) minmax(840px, 1fr);
  max-height: calc(100vh - 174px);
  overflow: auto;
}
.time-gutter {
  position: relative;
  height: calc(var(--hour-height) * 24);
  background: #fbfcfe;
  border-right: 1px solid var(--grid-border);
  flex: none;
}
.time-label {
  position: absolute;
  right: 10px;
  transform: translateY(-50%);
  color: var(--muted);
  font-size: 12px;
  line-height: 1;
  white-space: nowrap;
}
.time-label:first-child { transform: translateY(0); top: 0 !important; }
.time-label:last-child { transform: translateY(-100%); }

.week-grid { position: relative; min-width: 840px; }
.day-column {
  position: relative;
  min-width: 0;
  border-right: 1px solid var(--grid-border);
  background: #fff;
  cursor: crosshair;
  overflow: hidden;
}
.day-column:last-child { border-right: 0; }
.day-column.today { background: linear-gradient(var(--today), var(--today)), #fff; }
.hour-line {
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--grid-soft);
  pointer-events: none;
}
.hour-line:nth-child(6n + 1) { background: var(--grid-border); }
.hour-line.last { bottom: 0; top: auto !important; background: var(--grid-border); }

.event-block {
  position: absolute;
  z-index: 3;
  border: 1px solid rgba(23, 73, 183, 0.34);
  border-left: 4px solid var(--blue-dark);
  border-radius: 8px;
  background: linear-gradient(135deg, #3b82f6, #2563eb);
  color: white;
  padding: 5px 6px;
  text-align: left;
  overflow: hidden;
  cursor: pointer;
  box-shadow: 0 4px 10px rgba(37, 99, 235, 0.20);
  min-width: 0;
}
.event-block:hover,
.event-block:focus { z-index: 5; filter: brightness(1.04); outline: 2px solid rgba(37, 99, 235, 0.28); }
.event-block strong,
.event-block span {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}
.event-block strong { font-size: 13px; line-height: 1.2; }
.event-block span { font-size: 11px; opacity: 0.92; margin-top: 2px; }

.selection-preview {
  position: absolute;
  left: 4px;
  right: 4px;
  z-index: 2;
  background: rgba(37, 99, 235, 0.16);
  border: 1px dashed var(--blue);
  border-radius: 8px;
  pointer-events: none;
}
.grid-message {
  position: absolute;
  top: 24px;
  left: 24px;
  right: 24px;
  padding: 14px 16px;
  background: #fff7ed;
  border: 1px solid #fed7aa;
  color: #9a3412;
  border-radius: 10px;
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  background: rgba(15, 23, 42, 0.42);
  padding: 20px;
}
.hidden { display: none !important; }
.event-form {
  width: min(560px, 100%);
  background: #fff;
  border-radius: 16px;
  box-shadow: 0 28px 70px rgba(15, 23, 42, 0.26);
  padding: 22px;
}
.event-form h2 { margin: 0 0 18px; }
.event-form label {
  display: flex;
  flex-direction: column;
  gap: 7px;
  color: var(--muted);
  font-size: 13px;
  font-weight: 700;
}
.event-form input {
  color: var(--text);
  border: 1px solid var(--grid-border);
  border-radius: 10px;
  padding: 10px 12px;
  outline: none;
}
.event-form input:focus { border-color: var(--blue); box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.13); }
.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 14px;
}
.form-error { min-height: 20px; margin: 10px 0 0; color: #dc2626; font-size: 13px; }
.form-actions { display: flex; gap: 8px; align-items: center; margin-top: 10px; }
.form-actions .spacer { flex: 1; }
.form-actions .primary { background: var(--blue); border-color: var(--blue); color: white; }
.form-actions .primary:hover { background: var(--blue-dark); }
.form-actions .danger { background: #fee2e2; border-color: #fecaca; color: #b91c1c; margin-right: auto; }
.form-actions .danger:hover { background: #fecaca; }

@media (max-width: 760px) {
  .toolbar { align-items: flex-start; flex-direction: column; gap: 12px; }
  .brand { margin-right: 0; }
  .range-label { text-align: left; }
  .calendar-shell { margin: 10px; }
  .calendar-header { top: 0; }
  .form-row { grid-template-columns: 1fr; }
}
"}

{"path": "server.js", "content": "import express from 'express';
import cors from 'cors';
import { PGlite } from '@electric-sql/pglite';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const PORT = process.env.PORT || 3000;

const app = express();
app.use(cors());
app.use(express.json());

const db = new PGlite(path.join(__dirname, 'pgdata'));

await db.query(`
  CREATE TABLE IF NOT EXISTS events (
    id SERIAL PRIMARY KEY,
    title TEXT NOT NULL,
    start_at TIMESTAMP NOT NULL,
    end_at TIMESTAMP NOT NULL,
    CONSTRAINT valid_event_time CHECK (end_at > start_at)
  );
`);

function isValidDate(value) {
  const d = new Date(value);
  return value && !Number.isNaN(d.getTime());
}

function validateEventPayload(body) {
  const title = typeof body.title === 'string' ? body.title.trim() : '';
  const start_at = body.start_at ?? body.start;
  const end_at = body.end_at ?? body.end;
  if (!title) return { error: 'Title is required' };
  if (!isValidDate(start_at) || !isValidDate(end_at)) return { error: 'Valid start_at and end_at are required' };
  if (new Date(end_at).getTime() <= new Date(start_at).getTime()) return { error: 'end_at must be after start_at' };
  return { title, start_at: new Date(start_at).toISOString(), end_at: new Date(end_at).toISOString() };
}

function rowToEvent(row) {
  return {
    id: row.id,
    title: row.title,
    start_at: new Date(row.start_at).toISOString(),
    end_at: new Date(row.end_at).toISOString(),
  };
}

app.get('/api/health', (req, res) => res.json({ ok: true }));

app.get('/api/events', async (req, res) => {
  try {
    const { start, end } = req.query;
    if (!isValidDate(start) || !isValidDate(end) || new Date(end) <= new Date(start)) {
      return res.status(400).json({ error: 'Valid start and end query parameters are required' });
    }
    const result = await db.query(
      `SELECT id, title, start_at, end_at
       FROM events
       WHERE start_at < $2::timestamp AND end_at > $1::timestamp
       ORDER BY start_at ASC, end_at ASC, id ASC`,
      [new Date(start).toISOString(), new Date(end).toISOString()]
    );
    res.json(result.rows.map(rowToEvent));
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to fetch events' });
  }
});

app.post('/api/events', async (req, res) => {
  try {
    const valid = validateEventPayload(req.body || {});
    if (valid.error) return res.status(400).json({ error: valid.error });
    const result = await db.query(
      `INSERT INTO events (title, start_at, end_at)
       VALUES ($1, $2::timestamp, $3::timestamp)
       RETURNING id, title, start_at, end_at`,
      [valid.title, valid.start_at, valid.end_at]
    );
    res.status(201).json(rowToEvent(result.rows[0]));
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to create event' });
  }
});

app.put('/api/events/:id', async (req, res) => {
  try {
    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) return res.status(400).json({ error: 'Invalid id' });
    const valid = validateEventPayload(req.body || {});
    if (valid.error) return res.status(400).json({ error: valid.error });
    const result = await db.query(
      `UPDATE events
       SET title = $1, start_at = $2::timestamp, end_at = $3::timestamp
       WHERE id = $4
       RETURNING id, title, start_at, end_at`,
      [valid.title, valid.start_at, valid.end_at, id]
    );
    if (result.rows.length === 0) return res.status(404).json({ error: 'Event not found' });
    res.json(rowToEvent(result.rows[0]));
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to update event' });
  }
});

app.delete('/api/events/:id', async (req, res) => {
  try {
    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) return res.status(400).json({ error: 'Invalid id' });
    const result = await db.query('DELETE FROM events WHERE id = $1 RETURNING id', [id]);
    if (result.rows.length === 0) return res.status(404).json({ error: 'Event not found' });
    res.status(204).end();
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to delete event' });
  }
});

app.listen(PORT, () => {
  console.log(`Calendar API listening on http://localhost:${PORT}`);
});
"}

{"path": "src/main.js", "content": "import './styles.css';

const API_BASE = 'http://localhost:3000/api';
const HOUR_HEIGHT = 64;
const DAY_HEIGHT = HOUR_HEIGHT * 24;
const SNAP_MINUTES = 15;
const DAY_NAMES = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

const app = document.querySelector('#app');
app.innerHTML = `
  <header class="toolbar">
    <div class="brand">
      <h1>Week Calendar</h1>
      <p>Minute-precision week view</p>
    </div>
    <nav class="nav-actions">
      <button id="prevWeek" type="button">← Previous</button>
      <button id="today" type="button">Today</button>
      <button id="nextWeek" type="button">Next →</button>
    </nav>
    <div id="rangeLabel" class="range-label"></div>
  </header>
  <main class="calendar-shell">
    <div class="calendar-header">
      <div class="time-gutter header-gutter"></div>
      <div id="dayHeaders" class="day-headers"></div>
    </div>
    <div class="calendar-scroll">
      <div class="time-gutter" id="timeGutter"></div>
      <div id="weekGrid" class="week-grid"></div>
    </div>
  </main>

  <div id="modalBackdrop" class="modal-backdrop hidden">
    <form id="eventForm" class="event-form">
      <h2 id="formTitle">New event</h2>
      <label>
        Title
        <input id="eventTitle" name="title" type="text" required maxlength="120" />
      </label>
      <div class="form-row">
        <label>
          Start
          <input id="eventStart" name="start" type="datetime-local" required />
        </label>
        <label>
          End
          <input id="eventEnd" name="end" type="datetime-local" required />
        </label>
      </div>
      <p id="formError" class="form-error" role="alert"></p>
      <div class="form-actions">
        <button id="deleteEvent" class="danger hidden" type="button">Delete</button>
        <span class="spacer"></span>
        <button id="cancelForm" type="button">Cancel</button>
        <button class="primary" type="submit">Save</button>
      </div>
    </form>
  </div>
`;

let weekStart = startOfWeek(new Date());
let events = [];
let editingEvent = null;
let dragState = null;

const els = {
  prevWeek: document.querySelector('#prevWeek'),
  today: document.querySelector('#today'),
  nextWeek: document.querySelector('#nextWeek'),
  rangeLabel: document.querySelector('#rangeLabel'),
  dayHeaders: document.querySelector('#dayHeaders'),
  timeGutter: document.querySelector('#timeGutter'),
  weekGrid: document.querySelector('#weekGrid'),
  modalBackdrop: document.querySelector('#modalBackdrop'),
  eventForm: document.querySelector('#eventForm'),
  formTitle: document.querySelector('#formTitle'),
  eventTitle: document.querySelector('#eventTitle'),
  eventStart: document.querySelector('#eventStart'),
  eventEnd: document.querySelector('#eventEnd'),
  formError: document.querySelector('#formError'),
  deleteEvent: document.querySelector('#deleteEvent'),
  cancelForm: document.querySelector('#cancelForm'),
};

initStaticGrid();
attachHandlers();
loadWeek();

function initStaticGrid() {
  els.timeGutter.innerHTML = '';
  for (let h = 0; h <= 24; h++) {
    const label = document.createElement('div');
    label.className = 'time-label';
    label.style.top = `${h * HOUR_HEIGHT}px`;
    label.textContent = `${String(h).padStart(2, '0')}:00`;
    els.timeGutter.appendChild(label);
  }
}

function attachHandlers() {
  els.prevWeek.addEventListener('click', () => changeWeek(-7));
  els.nextWeek.addEventListener('click', () => changeWeek(7));
  els.today.addEventListener('click', () => { weekStart = startOfWeek(new Date()); loadWeek(); });
  els.cancelForm.addEventListener('click', closeModal);
  els.modalBackdrop.addEventListener('mousedown', (e) => { if (e.target === els.modalBackdrop) closeModal(); });
  els.eventForm.addEventListener('submit', saveEvent);
  els.deleteEvent.addEventListener('click', deleteCurrentEvent);
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') closeModal(); });
}

async function loadWeek() {
  renderHeaders();
  try {
    const start = weekStart.toISOString();
    const end = addDays(weekStart, 7).toISOString();
    const res = await fetch(`${API_BASE}/events?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}`);
    if (!res.ok) throw new Error('Failed to load events');
    events = await res.json();
    renderWeekGrid();
  } catch (err) {
    console.error(err);
    events = [];
    renderWeekGrid('Could not load events. Is the API server running?');
  }
}

function renderHeaders() {
  const end = addDays(weekStart, 6);
  els.rangeLabel.textContent = `${formatMonthDay(weekStart)} – ${formatMonthDay(end)} ${end.getFullYear()}`;
  els.dayHeaders.innerHTML = '';
  const todayKey = dateKey(new Date());
  for (let i = 0; i < 7; i++) {
    const d = addDays(weekStart, i);
    const header = document.createElement('div');
    header.className = `day-header ${dateKey(d) === todayKey ? 'today' : ''}`;
    header.innerHTML = `<span>${DAY_NAMES[i]}</span><strong>${d.getDate()}</strong>`;
    els.dayHeaders.appendChild(header);
  }
}

function renderWeekGrid(errorMessage = '') {
  els.weekGrid.innerHTML = '';
  els.weekGrid.style.height = `${DAY_HEIGHT}px`;
  for (let i = 0; i < 7; i++) {
    const day = addDays(weekStart, i);
    const col = document.createElement('section');
    col.className = `day-column ${dateKey(day) === dateKey(new Date()) ? 'today' : ''}`;
    col.dataset.dayIndex = String(i);
    col.style.height = `${DAY_HEIGHT}px`;
    for (let h = 0; h <= 24; h++) {
      const line = document.createElement('div');
      line.className = h === 24 ? 'hour-line last' : 'hour-line';
      line.style.top = `${h * HOUR_HEIGHT}px`;
      col.appendChild(line);
    }
    setupSelectionHandlers(col, day);
    els.weekGrid.appendChild(col);
  }

  if (errorMessage) {
    const msg = document.createElement('div');
    msg.className = 'grid-message';
    msg.textContent = errorMessage;
    els.weekGrid.appendChild(msg);
    return;
  }

  const byDay = splitAndGroupEventsByDay(events);
  byDay.forEach((dayEvents, dayIndex) => {
    const col = els.weekGrid.querySelector(`[data-day-index="${dayIndex}"]`);
    layoutDayEvents(dayEvents).forEach((item) => {
      const el = document.createElement('button');
      el.type = 'button';
      el.className = 'event-block';
      el.style.top = `${item.top}px`;
      el.style.height = `${item.height}px`;
      el.style.left = `calc(${item.leftPct}% + 3px)`;
      el.style.width = `calc(${item.widthPct}% - 6px)`;
      el.innerHTML = `<strong title="${escapeHtml(item.event.title)}">${escapeHtml(item.event.title)}</strong><span>${formatTime(item.visibleStart)}–${formatTime(item.visibleEnd)}</span>`;
      el.addEventListener('click', (e) => {
        e.stopPropagation();
        openEditForm(item.event);
      });
      col.appendChild(el);
    });
  });
}

function splitAndGroupEventsByDay(rawEvents) {
  const days = Array.from({ length: 7 }, () => []);
  const weekEnd = addDays(weekStart, 7);
  rawEvents.forEach((event) => {
    const originalStart = new Date(event.start_at);
    const originalEnd = new Date(event.end_at);
    for (let i = 0; i < 7; i++) {
      const dayStart = addDays(weekStart, i);
      const dayEnd = addDays(dayStart, 1);
      const visibleStart = maxDate(originalStart, dayStart);
      const visibleEnd = minDate(originalEnd, dayEnd, weekEnd);
      if (visibleStart < visibleEnd) {
        days[i].push({ event, visibleStart, visibleEnd });
      }
    }
  });
  return days;
}

function layoutDayEvents(dayEvents) {
  const sorted = [...dayEvents].sort((a, b) => a.visibleStart - b.visibleStart || a.visibleEnd - b.visibleEnd || a.event.id - b.event.id);
  const clusters = [];
  let current = [];
  let clusterEnd = null;

  sorted.forEach((item) => {
    if (current.length === 0 || item.visibleStart < clusterEnd) {
      current.push(item);
      clusterEnd = clusterEnd ? maxDate(clusterEnd, item.visibleEnd) : item.visibleEnd;
    } else {
      clusters.push(current);
      current = [item];
      clusterEnd = item.visibleEnd;
    }
  });
  if (current.length) clusters.push(current);

  const laidOut = [];
  clusters.forEach((cluster) => {
    const columns = [];
    const placements = [];
    cluster.forEach((item) => {
      let colIndex = columns.findIndex((end) => end <= item.visibleStart);
      if (colIndex === -1) {
        colIndex = columns.length;
        columns.push(item.visibleEnd);
      } else {
        columns[colIndex] = item.visibleEnd;
      }
      placements.push({ item, colIndex });
    });
    const colCount = Math.max(columns.length, 1);
    placements.forEach(({ item, colIndex }) => {
      const startMin = minutesSinceMidnight(item.visibleStart);
      const endMin = minutesSinceMidnight(item.visibleEnd);
      laidOut.push({
        ...item,
        top: (startMin / 60) * HOUR_HEIGHT,
        height: Math.max(1, ((endMin - startMin) / 60) * HOUR_HEIGHT),
        leftPct: (colIndex / colCount) * 100,
        widthPct: 100 / colCount,
      });
    });
  });
  return laidOut;
}

function setupSelectionHandlers(col, day) {
  col.addEventListener('mousedown', (e) => {
    if (e.button !== 0 || e.target.closest('.event-block')) return;
    const rect = col.getBoundingClientRect();
    const startY = clamp(e.clientY - rect.top, 0, DAY_HEIGHT);
    const preview = document.createElement('div');
    preview.className = 'selection-preview';
    preview.style.top = `${startY}px`;
    preview.style.height = '1px';
    col.appendChild(preview);
    dragState = { col, day, rect, startY, currentY: startY, preview, moved: false };
    e.preventDefault();
  });

  col.addEventListener('click', (e) => {
    if (e.target.closest('.event-block') || dragState) return;
    const rect = col.getBoundingClientRect();
    const y = clamp(e.clientY - rect.top, 0, DAY_HEIGHT - 1);
    const startMin = snapMinutes((y / DAY_HEIGHT) * 1440);
    openCreateForm(dateAtMinutes(day, startMin), dateAtMinutes(day, Math.min(startMin + 60, 1440)));
  });
}

document.addEventListener('mousemove', (e) => {
  if (!dragState) return;
  const y = clamp(e.clientY - dragState.rect.top, 0, DAY_HEIGHT);
  dragState.currentY = y;
  if (Math.abs(y - dragState.startY) > 3) dragState.moved = true;
  const top = Math.min(dragState.startY, y);
  const height = Math.max(1, Math.abs(y - dragState.startY));
  dragState.preview.style.top = `${top}px`;
  dragState.preview.style.height = `${height}px`;
});

document.addEventListener('mouseup', () => {
  if (!dragState) return;
  const state = dragState;
  dragState = null;
  state.preview.remove();
  if (!state.moved) return;
  let a = snapMinutes((Math.min(state.startY, state.currentY) / DAY_HEIGHT) * 1440);
  let b = snapMinutes((Math.max(state.startY, state.currentY) / DAY_HEIGHT) * 1440);
  if (b <= a) b = Math.min(a + SNAP_MINUTES, 1440);
  openCreateForm(dateAtMinutes(state.day, a), dateAtMinutes(state.day, b));
});

function openCreateForm(start, end) {
  editingEvent = null;
  els.formTitle.textContent = 'New event';
  els.eventTitle.value = '';
  els.eventStart.value = toDatetimeLocalValue(start);
  els.eventEnd.value = toDatetimeLocalValue(end);
  els.deleteEvent.classList.add('hidden');
  els.formError.textContent = '';
  els.modalBackdrop.classList.remove('hidden');
  els.eventTitle.focus();
}

function openEditForm(event) {
  editingEvent = event;
  els.formTitle.textContent = 'Edit event';
  els.eventTitle.value = event.title;
  els.eventStart.value = toDatetimeLocalValue(new Date(event.start_at));
  els.eventEnd.value = toDatetimeLocalValue(new Date(event.end_at));
  els.deleteEvent.classList.remove('hidden');
  els.formError.textContent = '';
  els.modalBackdrop.classList.remove('hidden');
  els.eventTitle.focus();
}

function closeModal() {
  els.modalBackdrop.classList.add('hidden');
  editingEvent = null;
}

async function saveEvent(e) {
  e.preventDefault();
  els.formError.textContent = '';
  const payload = {
    title: els.eventTitle.value.trim(),
    start_at: new Date(els.eventStart.value).toISOString(),
    end_at: new Date(els.eventEnd.value).toISOString(),
  };
  if (!payload.title) return (els.formError.textContent = 'Title is required.');
  if (new Date(payload.end_at) <= new Date(payload.start_at)) return (els.formError.textContent = 'End must be after start.');
  try {
    const url = editingEvent ? `${API_BASE}/events/${editingEvent.id}` : `${API_BASE}/events`;
    const method = editingEvent ? 'PUT' : 'POST';
    const res = await fetch(url, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      throw new Error(err.error || 'Save failed');
    }
    closeModal();
    await loadWeek();
  } catch (err) {
    els.formError.textContent = err.message;
  }
}

async function deleteCurrentEvent() {
  if (!editingEvent) return;
  if (!confirm('Delete this event?')) return;
  try {
    const res = await fetch(`${API_BASE}/events/${editingEvent.id}`, { method: 'DELETE' });
    if (!res.ok) throw new Error('Delete failed');
    closeModal();
    await loadWeek();
  } catch (err) {
    els.formError.textContent = err.message;
  }
}

function changeWeek(days) {
  weekStart = addDays(weekStart, days);
  loadWeek();
}

function startOfWeek(date) {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  const day = d.getDay();
  const diff = (day + 6) % 7;
  d.setDate(d.getDate() - diff);
  return d;
}

function addDays(date, days) {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

function dateAtMinutes(day, minutes) {
  const d = new Date(day);
  d.setHours(0, 0, 0, 0);
  d.setMinutes(minutes);
  return d;
}

function minutesSinceMidnight(date) {
  return date.getHours() * 60 + date.getMinutes() + date.getSeconds() / 60 + date.getMilliseconds() / 60000;
}

function snapMinutes(minutes) {
  return clamp(Math.round(minutes / SNAP_MINUTES) * SNAP_MINUTES, 0, 1440);
}

function toDatetimeLocalValue(date) {
  const d = new Date(date);
  const pad = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function formatTime(date) {
  return `${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
}

function formatMonthDay(date) {
  return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
}

function dateKey(date) {
  const d = new Date(date);
  return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
}

function minDate(...dates) {
  return new Date(Math.min(...dates.map((d) => new Date(d).getTime())));
}

function maxDate(...dates) {
  return new Date(Math.max(...dates.map((d) => new Date(d).getTime())));
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function escapeHtml(value) {
  return String(value).replace(/[&<>'"]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[ch]));
}
"}

{"path": "src/styles.css", "content": ":root {
  --gutter-width: 72px;
  --header-height: 72px;
  --hour-height: 64px;
  --grid-border: #d8dee8;
  --grid-soft: #eef2f7;
  --text: #152238;
  --muted: #687589;
  --blue: #2563eb;
  --blue-dark: #1749b7;
  --today: #eff6ff;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--text);
  background: #f7f9fc;
}

* { box-sizing: border-box; }
html, body, #app { margin: 0; min-height: 100%; }
button, input { font: inherit; }

.toolbar {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 18px 24px;
  background: #ffffff;
  border-bottom: 1px solid var(--grid-border);
  position: sticky;
  top: 0;
  z-index: 20;
}

.brand { margin-right: auto; }
.brand h1 { margin: 0; font-size: 22px; line-height: 1.1; }
.brand p { margin: 3px 0 0; color: var(--muted); font-size: 13px; }
.nav-actions { display: flex; gap: 8px; }
.nav-actions button,
.form-actions button {
  border: 1px solid var(--grid-border);
  background: #fff;
  border-radius: 9px;
  padding: 8px 12px;
  cursor: pointer;
  color: var(--text);
}
.nav-actions button:hover,
.form-actions button:hover { background: #f2f5f9; }
.range-label { min-width: 190px; text-align: right; color: var(--muted); font-weight: 600; }

.calendar-shell {
  margin: 18px 24px 28px;
  border: 1px solid var(--grid-border);
  border-radius: 14px;
  overflow: hidden;
  background: white;
  box-shadow: 0 12px 32px rgba(21, 34, 56, 0.08);
}

.calendar-header {
  display: grid;
  grid-template-columns: var(--gutter-width) 1fr;
  height: var(--header-height);
  border-bottom: 1px solid var(--grid-border);
  background: #fff;
  position: sticky;
  top: 79px;
  z-index: 10;
}
.header-gutter { border-right: 1px solid var(--grid-border); }
.day-headers,
.week-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(120px, 1fr));
}
.day-header {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 4px;
  border-right: 1px solid var(--grid-border);
  color: var(--muted);
}
.day-header:last-child { border-right: 0; }
.day-header strong {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  font-size: 18px;
  color: var(--text);
}
.day-header.today { background: var(--today); color: var(--blue); }
.day-header.today strong { background: var(--blue); color: white; }

.calendar-scroll {
  display: grid;
  grid-template-columns: var(--gutter-width) minmax(840px, 1fr);
  max-height: calc(100vh - 174px);
  overflow: auto;
}
.time-gutter {
  position: relative;
  height: calc(var(--hour-height) * 24);
  background: #fbfcfe;
  border-right: 1px solid var(--grid-border);
  flex: none;
}
.time-label {
  position: absolute;
  right: 10px;
  transform: translateY(-50%);
  color: var(--muted);
  font-size: 12px;
  line-height: 1;
  white-space: nowrap;
}
.time-label:first-child { transform: translateY(0); top: 0 !important; }
.time-label:last-child { transform: translateY(-100%); }

.week-grid { position: relative; min-width: 840px; }
.day-column {
  position: relative;
  min-width: 0;
  border-right: 1px solid var(--grid-border);
  background: #fff;
  cursor: crosshair;
  overflow: hidden;
}
.day-column:last-child { border-right: 0; }
.day-column.today { background: linear-gradient(var(--today), var(--today)), #fff; }
.hour-line {
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--grid-soft);
  pointer-events: none;
}
.hour-line:nth-child(6n + 1) { background: var(--grid-border); }
.hour-line.last { bottom: 0; top: auto !important; background: var(--grid-border); }

.event-block {
  position: absolute;
  z-index: 3;
  border: 1px solid rgba(23, 73, 183, 0.34);
  border-left: 4px solid var(--blue-dark);
  border-radius: 8px;
  background: linear-gradient(135deg, #3b82f6, #2563eb);
  color: white;
  padding: 5px 6px;
  text-align: left;
  overflow: hidden;
  cursor: pointer;
  box-shadow: 0 4px 10px rgba(37, 99, 235, 0.20);
  min-width: 0;
}
.event-block:hover,
.event-block:focus { z-index: 5; filter: brightness(1.04); outline: 2px solid rgba(37, 99, 235, 0.28); }
.event-block strong,
.event-block span {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}
.event-block strong { font-size: 13px; line-height: 1.2; }
.event-block span { font-size: 11px; opacity: 0.92; margin-top: 2px; }

.selection-preview {
  position: absolute;
  left: 4px;
  right: 4px;
  z-index: 2;
  background: rgba(37, 99, 235, 0.16);
  border: 1px dashed var(--blue);
  border-radius: 8px;
  pointer-events: none;
}
.grid-message {
  position: absolute;
  top: 24px;
  left: 24px;
  right: 24px;
  padding: 14px 16px;
  background: #fff7ed;
  border: 1px solid #fed7aa;
  color: #9a3412;
  border-radius: 10px;
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  background: rgba(15, 23, 42, 0.42);
  padding: 20px;
}
.hidden { display: none !important; }
.event-form {
  width: min(560px, 100%);
  background: #fff;
  border-radius: 16px;
  box-shadow: 0 28px 70px rgba(15, 23, 42, 0.26);
  padding: 22px;
}
.event-form h2 { margin: 0 0 18px; }
.event-form label {
  display: flex;
  flex-direction: column;
  gap: 7px;
  color: var(--muted);
  font-size: 13px;
  font-weight: 700;
}
.event-form input {
  color: var(--text);
  border: 1px solid var(--grid-border);
  border-radius: 10px;
  padding: 10px 12px;
  outline: none;
}
.event-form input:focus { border-color: var(--blue); box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.13); }
.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 14px;
}
.form-error { min-height: 20px; margin: 10px 0 0; color: #dc2626; font-size: 13px; }
.form-actions { display: flex; gap: 8px; align-items: center; margin-top: 10px; }
.form-actions .spacer { flex: 1; }
.form-actions .primary { background: var(--blue); border-color: var(--blue); color: white; }
.form-actions .primary:hover { background: var(--blue-dark); }
.form-actions .danger { background: #fee2e2; border-color: #fecaca; color: #b91c1c; margin-right: auto; }
.form-actions .danger:hover { background: #fecaca; }

@media (max-width: 760px) {
  .toolbar { align-items: flex-start; flex-direction: column; gap: 12px; }
  .brand { margin-right: 0; }
  .range-label { text-align: left; }
  .calendar-shell { margin: 10px; }
  .calendar-header { top: 0; }
  .form-row { grid-template-columns: 1fr; }
}
"}

{"path": "server.js", "content": "import express from 'express';
import cors from 'cors';
import { PGlite } from '@electric-sql/pglite';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const PORT = process.env.PORT || 3000;

const app = express();
app.use(cors());
app.use(express.json());

const db = new PGlite(path.join(__dirname, 'pgdata'));

await db.query(`
  CREATE TABLE IF NOT EXISTS events (
    id SERIAL PRIMARY KEY,
    title TEXT NOT NULL,
    start_at TIMESTAMP NOT NULL,
    end_at TIMESTAMP NOT NULL,
    CONSTRAINT valid_event_time CHECK (end_at > start_at)
  );
`);

function isValidDate(value) {
  const d = new Date(value);
  return value && !Number.isNaN(d.getTime());
}

function validateEventPayload(body) {
  const title = typeof body.title === 'string' ? body.title.trim() : '';
  const start_at = body.start_at ?? body.start;
  const end_at = body.end_at ?? body.end;
  if (!title) return { error: 'Title is required' };
  if (!isValidDate(start_at) || !isValidDate(end_at)) return { error: 'Valid start_at and end_at are required' };
  if (new Date(end_at).getTime() <= new Date(start_at).getTime()) return { error: 'end_at must be after start_at' };
  return { title, start_at: new Date(start_at).toISOString(), end_at: new Date(end_at).toISOString() };
}

function rowToEvent(row) {
  return {
    id: row.id,
    title: row.title,
    start_at: new Date(row.start_at).toISOString(),
    end_at: new Date(row.end_at).toISOString(),
  };
}

app.get('/api/health', (req, res) => res.json({ ok: true }));

app.get('/api/events', async (req, res) => {
  try {
    const { start, end } = req.query;
    if (!isValidDate(start) || !isValidDate(end) || new Date(end) <= new Date(start)) {
      return res.status(400).json({ error: 'Valid start and end query parameters are required' });
    }
    const result = await db.query(
      `SELECT id, title, start_at, end_at
       FROM events
       WHERE start_at < $2::timestamp AND end_at > $1::timestamp
       ORDER BY start_at ASC, end_at ASC, id ASC`,
      [new Date(start).toISOString(), new Date(end).toISOString()]
    );
    res.json(result.rows.map(rowToEvent));
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to fetch events' });
  }
});

app.post('/api/events', async (req, res) => {
  try {
    const valid = validateEventPayload(req.body || {});
    if (valid.error) return res.status(400).json({ error: valid.error });
    const result = await db.query(
      `INSERT INTO events (title, start_at, end_at)
       VALUES ($1, $2::timestamp, $3::timestamp)
       RETURNING id, title, start_at, end_at`,
      [valid.title, valid.start_at, valid.end_at]
    );
    res.status(201).json(rowToEvent(result.rows[0]));
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to create event' });
  }
});

app.put('/api/events/:id', async (req, res) => {
  try {
    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) return res.status(400).json({ error: 'Invalid id' });
    const valid = validateEventPayload(req.body || {});
    if (valid.error) return res.status(400).json({ error: valid.error });
    const result = await db.query(
      `UPDATE events
       SET title = $1, start_at = $2::timestamp, end_at = $3::timestamp
       WHERE id = $4
       RETURNING id, title, start_at, end_at`,
      [valid.title, valid.start_at, valid.end_at, id]
    );
    if (result.rows.length === 0) return res.status(404).json({ error: 'Event not found' });
    res.json(rowToEvent(result.rows[0]));
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to update event' });
  }
});

app.delete('/api/events/:id', async (req, res) => {
  try {
    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) return res.status(400).json({ error: 'Invalid id' });
    const result = await db.query('DELETE FROM events WHERE id = $1 RETURNING id', [id]);
    if (result.rows.length === 0) return res.status(404).json({ error: 'Event not found' });
    res.status(204).end();
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to delete event' });
  }
});

app.listen(PORT, () => {
  console.log(`Calendar API listening on http://localhost:${PORT}`);
});
"}

{"path": "src/main.js", "content": "import './styles.css';

const API_BASE = 'http://localhost:3000/api';
const HOUR_HEIGHT = 64;
const DAY_HEIGHT = HOUR_HEIGHT * 24;
const SNAP_MINUTES = 15;
const DAY_NAMES = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

const app = document.querySelector('#app');
app.innerHTML = `
  <header class="toolbar">
    <div class="brand">
      <h1>Week Calendar</h1>
      <p>Minute-precision week view</p>
    </div>
    <nav class="nav-actions">
      <button id="prevWeek" type="button">← Previous</button>
      <button id="today" type="button">Today</button>
      <button id="nextWeek" type="button">Next →</button>
    </nav>
    <div id="rangeLabel" class="range-label"></div>
  </header>
  <main class="calendar-shell">
    <div class="calendar-header">
      <div class="time-gutter header-gutter"></div>
      <div id="dayHeaders" class="day-headers"></div>
    </div>
    <div class="calendar-scroll">
      <div class="time-gutter" id="timeGutter"></div>
      <div id="weekGrid" class="week-grid"></div>
    </div>
  </main>

  <div id="modalBackdrop" class="modal-backdrop hidden">
    <form id="eventForm" class="event-form">
      <h2 id="formTitle">New event</h2>
      <label>
        Title
        <input id="eventTitle" name="title" type="text" required maxlength="120" />
      </label>
      <div class="form-row">
        <label>
          Start
          <input id="eventStart" name="start" type="datetime-local" required />
        </label>
        <label>
          End
          <input id="eventEnd" name="end" type="datetime-local" required />
        </label>
      </div>
      <p id="formError" class="form-error" role="alert"></p>
      <div class="form-actions">
        <button id="deleteEvent" class="danger hidden" type="button">Delete</button>
        <span class="spacer"></span>
        <button id="cancelForm" type="button">Cancel</button>
        <button class="primary" type="submit">Save</button>
      </div>
    </form>
  </div>
`;

let weekStart = startOfWeek(new Date());
let events = [];
let editingEvent = null;
let dragState = null;

const els = {
  prevWeek: document.querySelector('#prevWeek'),
  today: document.querySelector('#today'),
  nextWeek: document.querySelector('#nextWeek'),
  rangeLabel: document.querySelector('#rangeLabel'),
  dayHeaders: document.querySelector('#dayHeaders'),
  timeGutter: document.querySelector('#timeGutter'),
  weekGrid: document.querySelector('#weekGrid'),
  modalBackdrop: document.querySelector('#modalBackdrop'),
  eventForm: document.querySelector('#eventForm'),
  formTitle: document.querySelector('#formTitle'),
  eventTitle: document.querySelector('#eventTitle'),
  eventStart: document.querySelector('#eventStart'),
  eventEnd: document.querySelector('#eventEnd'),
  formError: document.querySelector('#formError'),
  deleteEvent: document.querySelector('#deleteEvent'),
  cancelForm: document.querySelector('#cancelForm'),
};

initStaticGrid();
attachHandlers();
loadWeek();

function initStaticGrid() {
  els.timeGutter.innerHTML = '';
  for (let h = 0; h <= 24; h++) {
    const label = document.createElement('div');
    label.className = 'time-label';
    label.style.top = `${h * HOUR_HEIGHT}px`;
    label.textContent = `${String(h).padStart(2, '0')}:00`;
    els.timeGutter.appendChild(label);
  }
}

function attachHandlers() {
  els.prevWeek.addEventListener('click', () => changeWeek(-7));
  els.nextWeek.addEventListener('click', () => changeWeek(7));
  els.today.addEventListener('click', () => { weekStart = startOfWeek(new Date()); loadWeek(); });
  els.cancelForm.addEventListener('click', closeModal);
  els.modalBackdrop.addEventListener('mousedown', (e) => { if (e.target === els.modalBackdrop) closeModal(); });
  els.eventForm.addEventListener('submit', saveEvent);
  els.deleteEvent.addEventListener('click', deleteCurrentEvent);
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') closeModal(); });
}

async function loadWeek() {
  renderHeaders();
  try {
    const start = weekStart.toISOString();
    const end = addDays(weekStart, 7).toISOString();
    const res = await fetch(`${API_BASE}/events?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}`);
    if (!res.ok) throw new Error('Failed to load events');
    events = await res.json();
    renderWeekGrid();
  } catch (err) {
    console.error(err);
    events = [];
    renderWeekGrid('Could not load events. Is the API server running?');
  }
}

function renderHeaders() {
  const end = addDays(weekStart, 6);
  els.rangeLabel.textContent = `${formatMonthDay(weekStart)} – ${formatMonthDay(end)} ${end.getFullYear()}`;
  els.dayHeaders.innerHTML = '';
  const todayKey = dateKey(new Date());
  for (let i = 0; i < 7; i++) {
    const d = addDays(weekStart, i);
    const header = document.createElement('div');
    header.className = `day-header ${dateKey(d) === todayKey ? 'today' : ''}`;
    header.innerHTML = `<span>${DAY_NAMES[i]}</span><strong>${d.getDate()}</strong>`;
    els.dayHeaders.appendChild(header);
  }
}

function renderWeekGrid(errorMessage = '') {
  els.weekGrid.innerHTML = '';
  els.weekGrid.style.height = `${DAY_HEIGHT}px`;
  for (let i = 0; i < 7; i++) {
    const day = addDays(weekStart, i);
    const col = document.createElement('section');
    col.className = `day-column ${dateKey(day) === dateKey(new Date()) ? 'today' : ''}`;
    col.dataset.dayIndex = String(i);
    col.style.height = `${DAY_HEIGHT}px`;
    for (let h = 0; h <= 24; h++) {
      const line = document.createElement('div');
      line.className = h === 24 ? 'hour-line last' : 'hour-line';
      line.style.top = `${h * HOUR_HEIGHT}px`;
      col.appendChild(line);
    }
    setupSelectionHandlers(col, day);
    els.weekGrid.appendChild(col);
  }

  if (errorMessage) {
    const msg = document.createElement('div');
    msg.className = 'grid-message';
    msg.textContent = errorMessage;
    els.weekGrid.appendChild(msg);
    return;
  }

  const byDay = splitAndGroupEventsByDay(events);
  byDay.forEach((dayEvents, dayIndex) => {
    const col = els.weekGrid.querySelector(`[data-day-index="${dayIndex}"]`);
    layoutDayEvents(dayEvents).forEach((item) => {
      const el = document.createElement('button');
      el.type = 'button';
      el.className = 'event-block';
      el.style.top = `${item.top}px`;
      el.style.height = `${item.height}px`;
      el.style.left = `calc(${item.leftPct}% + 3px)`;
      el.style.width = `calc(${item.widthPct}% - 6px)`;
      el.innerHTML = `<strong title="${escapeHtml(item.event.title)}">${escapeHtml(item.event.title)}</strong><span>${formatTime(item.visibleStart)}–${formatTime(item.visibleEnd)}</span>`;
      el.addEventListener('click', (e) => {
        e.stopPropagation();
        openEditForm(item.event);
      });
      col.appendChild(el);
    });
  });
}

function splitAndGroupEventsByDay(rawEvents) {
  const days = Array.from({ length: 7 }, () => []);
  const weekEnd = addDays(weekStart, 7);
  rawEvents.forEach((event) => {
    const originalStart = new Date(event.start_at);
    const originalEnd = new Date(event.end_at);
    for (let i = 0; i < 7; i++) {
      const dayStart = addDays(weekStart, i);
      const dayEnd = addDays(dayStart, 1);
      const visibleStart = maxDate(originalStart, dayStart);
      const visibleEnd = minDate(originalEnd, dayEnd, weekEnd);
      if (visibleStart < visibleEnd) {
        days[i].push({ event, visibleStart, visibleEnd });
      }
    }
  });
  return days;
}

function layoutDayEvents(dayEvents) {
  const sorted = [...dayEvents].sort((a, b) => a.visibleStart - b.visibleStart || a.visibleEnd - b.visibleEnd || a.event.id - b.event.id);
  const clusters = [];
  let current = [];
  let clusterEnd = null;

  sorted.forEach((item) => {
    if (current.length === 0 || item.visibleStart < clusterEnd) {
      current.push(item);
      clusterEnd = clusterEnd ? maxDate(clusterEnd, item.visibleEnd) : item.visibleEnd;
    } else {
      clusters.push(current);
      current = [item];
      clusterEnd = item.visibleEnd;
    }
  });
  if (current.length) clusters.push(current);

  const laidOut = [];
  clusters.forEach((cluster) => {
    const columns = [];
    const placements = [];
    cluster.forEach((item) => {
      let colIndex = columns.findIndex((end) => end <= item.visibleStart);
      if (colIndex === -1) {
        colIndex = columns.length;
        columns.push(item.visibleEnd);
      } else {
        columns[colIndex] = item.visibleEnd;
      }
      placements.push({ item, colIndex });
    });
    const colCount = Math.max(columns.length, 1);
    placements.forEach(({ item, colIndex }) => {
      const startMin = minutesSinceMidnight(item.visibleStart);
      const endMin = minutesSinceMidnight(item.visibleEnd);
      laidOut.push({
        ...item,
        top: (startMin / 60) * HOUR_HEIGHT,
        height: Math.max(1, ((endMin - startMin) / 60) * HOUR_HEIGHT),
        leftPct: (colIndex / colCount) * 100,
        widthPct: 100 / colCount,
      });
    });
  });
  return laidOut;
}

function setupSelectionHandlers(col, day) {
  col.addEventListener('mousedown', (e) => {
    if (e.button !== 0 || e.target.closest('.event-block')) return;
    const rect = col.getBoundingClientRect();
    const startY = clamp(e.clientY - rect.top, 0, DAY_HEIGHT);
    const preview = document.createElement('div');
    preview.className = 'selection-preview';
    preview.style.top = `${startY}px`;
    preview.style.height = '1px';
    col.appendChild(preview);
    dragState = { col, day, rect, startY, currentY: startY, preview, moved: false };
    e.preventDefault();
  });

  col.addEventListener('click', (e) => {
    if (e.target.closest('.event-block') || dragState) return;
    const rect = col.getBoundingClientRect();
    const y = clamp(e.clientY - rect.top, 0, DAY_HEIGHT - 1);
    const startMin = snapMinutes((y / DAY_HEIGHT) * 1440);
    openCreateForm(dateAtMinutes(day, startMin), dateAtMinutes(day, Math.min(startMin + 60, 1440)));
  });
}

document.addEventListener('mousemove', (e) => {
  if (!dragState) return;
  const y = clamp(e.clientY - dragState.rect.top, 0, DAY_HEIGHT);
  dragState.currentY = y;
  if (Math.abs(y - dragState.startY) > 3) dragState.moved = true;
  const top = Math.min(dragState.startY, y);
  const height = Math.max(1, Math.abs(y - dragState.startY));
  dragState.preview.style.top = `${top}px`;
  dragState.preview.style.height = `${height}px`;
});

document.addEventListener('mouseup', () => {
  if (!dragState) return;
  const state = dragState;
  dragState = null;
  state.preview.remove();
  if (!state.moved) return;
  let a = snapMinutes((Math.min(state.startY, state.currentY) / DAY_HEIGHT) * 1440);
  let b = snapMinutes((Math.max(state.startY, state.currentY) / DAY_HEIGHT) * 1440);
  if (b <= a) b = Math.min(a + SNAP_MINUTES, 1440);
  openCreateForm(dateAtMinutes(state.day, a), dateAtMinutes(state.day, b));
});

function openCreateForm(start, end) {
  editingEvent = null;
  els.formTitle.textContent = 'New event';
  els.eventTitle.value = '';
  els.eventStart.value = toDatetimeLocalValue(start);
  els.eventEnd.value = toDatetimeLocalValue(end);
  els.deleteEvent.classList.add('hidden');
  els.formError.textContent = '';
  els.modalBackdrop.classList.remove('hidden');
  els.eventTitle.focus();
}

function openEditForm(event) {
  editingEvent = event;
  els.formTitle.textContent = 'Edit event';
  els.eventTitle.value = event.title;
  els.eventStart.value = toDatetimeLocalValue(new Date(event.start_at));
  els.eventEnd.value = toDatetimeLocalValue(new Date(event.end_at));
  els.deleteEvent.classList.remove('hidden');
  els.formError.textContent = '';
  els.modalBackdrop.classList.remove('hidden');
  els.eventTitle.focus();
}

function closeModal() {
  els.modalBackdrop.classList.add('hidden');
  editingEvent = null;
}

async function saveEvent(e) {
  e.preventDefault();
  els.formError.textContent = '';
  const payload = {
    title: els.eventTitle.value.trim(),
    start_at: new Date(els.eventStart.value).toISOString(),
    end_at: new Date(els.eventEnd.value).toISOString(),
  };
  if (!payload.title) return (els.formError.textContent = 'Title is required.');
  if (new Date(payload.end_at) <= new Date(payload.start_at)) return (els.formError.textContent = 'End must be after start.');
  try {
    const url = editingEvent ? `${API_BASE}/events/${editingEvent.id}` : `${API_BASE}/events`;
    const method = editingEvent ? 'PUT' : 'POST';
    const res = await fetch(url, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      throw new Error(err.error || 'Save failed');
    }
    closeModal();
    await loadWeek();
  } catch (err) {
    els.formError.textContent = err.message;
  }
}

async function deleteCurrentEvent() {
  if (!editingEvent) return;
  if (!confirm('Delete this event?')) return;
  try {
    const res = await fetch(`${API_BASE}/events/${editingEvent.id}`, { method: 'DELETE' });
    if (!res.ok) throw new Error('Delete failed');
    closeModal();
    await loadWeek();
  } catch (err) {
    els.formError.textContent = err.message;
  }
}

function changeWeek(days) {
  weekStart = addDays(weekStart, days);
  loadWeek();
}

function startOfWeek(date) {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  const day = d.getDay();
  const diff = (day + 6) % 7;
  d.setDate(d.getDate() - diff);
  return d;
}

function addDays(date, days) {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

function dateAtMinutes(day, minutes) {
  const d = new Date(day);
  d.setHours(0, 0, 0, 0);
  d.setMinutes(minutes);
  return d;
}

function minutesSinceMidnight(date) {
  return date.getHours() * 60 + date.getMinutes() + date.getSeconds() / 60 + date.getMilliseconds() / 60000;
}

function snapMinutes(minutes) {
  return clamp(Math.round(minutes / SNAP_MINUTES) * SNAP_MINUTES, 0, 1440);
}

function toDatetimeLocalValue(date) {
  const d = new Date(date);
  const pad = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function formatTime(date) {
  return `${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
}

function formatMonthDay(date) {
  return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
}

function dateKey(date) {
  const d = new Date(date);
  return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
}

function minDate(...dates) {
  return new Date(Math.min(...dates.map((d) => new Date(d).getTime())));
}

function maxDate(...dates) {
  return new Date(Math.max(...dates.map((d) => new Date(d).getTime())));
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function escapeHtml(value) {
  return String(value).replace(/[&<>'"]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[ch]));
}
"}

{"path": "src/styles.css", "content": ":root {
  --gutter-width: 72px;
  --header-height: 72px;
  --hour-height: 64px;
  --grid-border: #d8dee8;
  --grid-soft: #eef2f7;
  --text: #152238;
  --muted: #687589;
  --blue: #2563eb;
  --blue-dark: #1749b7;
  --today: #eff6ff;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--text);
  background: #f7f9fc;
}

* { box-sizing: border-box; }
html, body, #app { margin: 0; min-height: 100%; }
button, input { font: inherit; }

.toolbar {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 18px 24px;
  background: #ffffff;
  border-bottom: 1px solid var(--grid-border);
  position: sticky;
  top: 0;
  z-index: 20;
}

.brand { margin-right: auto; }
.brand h1 { margin: 0; font-size: 22px; line-height: 1.1; }
.brand p { margin: 3px 0 0; color: var(--muted); font-size: 13px; }
.nav-actions { display: flex; gap: 8px; }
.nav-actions button,
.form-actions button {
  border: 1px solid var(--grid-border);
  background: #fff;
  border-radius: 9px;
  padding: 8px 12px;
  cursor: pointer;
  color: var(--text);
}
.nav-actions button:hover,
.form-actions button:hover { background: #f2f5f9; }
.range-label { min-width: 190px; text-align: right; color: var(--muted); font-weight: 600; }

.calendar-shell {
  margin: 18px 24px 28px;
  border: 1px solid var(--grid-border);
  border-radius: 14px;
  overflow: hidden;
  background: white;
  box-shadow: 0 12px 32px rgba(21, 34, 56, 0.08);
}

.calendar-header {
  display: grid;
  grid-template-columns: var(--gutter-width) 1fr;
  height: var(--header-height);
  border-bottom: 1px solid var(--grid-border);
  background: #fff;
  position: sticky;
  top: 79px;
  z-index: 10;
}
.header-gutter { border-right: 1px solid var(--grid-border); }
.day-headers,
.week-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(120px, 1fr));
}
.day-header {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 4px;
  border-right: 1px solid var(--grid-border);
  color: var(--muted);
}
.day-header:last-child { border-right: 0; }
.day-header strong {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  font-size: 18px;
  color: var(--text);
}
.day-header.today { background: var(--today); color: var(--blue); }
.day-header.today strong { background: var(--blue); color: white; }

.calendar-scroll {
  display: grid;
  grid-template-columns: var(--gutter-width) minmax(840px, 1fr);
  max-height: calc(100vh - 174px);
  overflow: auto;
}
.time-gutter {
  position: relative;
  height: calc(var(--hour-height) * 24);
  background: #fbfcfe;
  border-right: 1px solid var(--grid-border);
  flex: none;
}
.time-label {
  position: absolute;
  right: 10px;
  transform: translateY(-50%);
  color: var(--muted);
  font-size: 12px;
  line-height: 1;
  white-space: nowrap;
}
.time-label:first-child { transform: translateY(0); top: 0 !important; }
.time-label:last-child { transform: translateY(-100%); }

.week-grid { position: relative; min-width: 840px; }
.day-column {
  position: relative;
  min-width: 0;
  border-right: 1px solid var(--grid-border);
  background: #fff;
  cursor: crosshair;
  overflow: hidden;
}
.day-column:last-child { border-right: 0; }
.day-column.today { background: linear-gradient(var(--today), var(--today)), #fff; }
.hour-line {
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--grid-soft);
  pointer-events: none;
}
.hour-line:nth-child(6n + 1) { background: var(--grid-border); }
.hour-line.last { bottom: 0; top: auto !important; background: var(--grid-border); }

.event-block {
  position: absolute;
  z-index: 3;
  border: 1px solid rgba(23, 73, 183, 0.34);
  border-left: 4px solid var(--blue-dark);
  border-radius: 8px;
  background: linear-gradient(135deg, #3b82f6, #2563eb);
  color: white;
  padding: 5px 6px;
  text-align: left;
  overflow: hidden;
  cursor: pointer;
  box-shadow: 0 4px 10px rgba(37, 99, 235, 0.20);
  min-width: 0;
}
.event-block:hover,
.event-block:focus { z-index: 5; filter: brightness(1.04); outline: 2px solid rgba(37, 99, 235, 0.28); }
.event-block strong,
.event-block span {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}
.event-block strong { font-size: 13px; line-height: 1.2; }
.event-block span { font-size: 11px; opacity: 0.92; margin-top: 2px; }

.selection-preview {
  position: absolute;
  left: 4px;
  right: 4px;
  z-index: 2;
  background: rgba(37, 99, 235, 0.16);
  border: 1px dashed var(--blue);
  border-radius: 8px;
  pointer-events: none;
}
.grid-message {
  position: absolute;
  top: 24px;
  left: 24px;
  right: 24px;
  padding: 14px 16px;
  background: #fff7ed;
  border: 1px solid #fed7aa;
  color: #9a3412;
  border-radius: 10px;
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  background: rgba(15, 23, 42, 0.42);
  padding: 20px;
}
.hidden { display: none !important; }
.event-form {
  width: min(560px, 100%);
  background: #fff;
  border-radius: 16px;
  box-shadow: 0 28px 70px rgba(15, 23, 42, 0.26);
  padding: 22px;
}
.event-form h2 { margin: 0 0 18px; }
.event-form label {
  display: flex;
  flex-direction: column;
  gap: 7px;
  color: var(--muted);
  font-size: 13px;
  font-weight: 700;
}
.event-form input {
  color: var(--text);
  border: 1px solid var(--grid-border);
  border-radius: 10px;
  padding: 10px 12px;
  outline: none;
}
.event-form input:focus { border-color: var(--blue); box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.13); }
.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 14px;
}
.form-error { min-height: 20px; margin: 10px 0 0; color: #dc2626; font-size: 13px; }
.form-actions { display: flex; gap: 8px; align-items: center; margin-top: 10px; }
.form-actions .spacer { flex: 1; }
.form-actions .primary { background: var(--blue); border-color: var(--blue); color: white; }
.form-actions .primary:hover { background: var(--blue-dark); }
.form-actions .danger { background: #fee2e2; border-color: #fecaca; color: #b91c1c; margin-right: auto; }
.form-actions .danger:hover { background: #fecaca; }

@media (max-width: 760px) {
  .toolbar { align-items: flex-start; flex-direction: column; gap: 12px; }
  .brand { margin-right: 0; }
  .range-label { text-align: left; }
  .calendar-shell { margin: 10px; }
  .calendar-header { top: 0; }
  .form-row { grid-template-columns: 1fr; }
}
"}

{"path": "server.js", "content": "import express from 'express';
import cors from 'cors';
import { PGlite } from '@electric-sql/pglite';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const PORT = process.env.PORT || 3000;

const app = express();
app.use(cors());
app.use(express.json());

const db = new PGlite(path.join(__dirname, 'pgdata'));

await db.query(`
  CREATE TABLE IF NOT EXISTS events (
    id SERIAL PRIMARY KEY,
    title TEXT NOT NULL,
    start_at TIMESTAMP NOT NULL,
    end_at TIMESTAMP NOT NULL,
    CONSTRAINT valid_event_time CHECK (end_at > start_at)
  );
`);

function isValidDate(value) {
  const d = new Date(value);
  return value && !Number.isNaN(d.getTime());
}

function validateEventPayload(body) {
  const title = typeof body.title === 'string' ? body.title.trim() : '';
  const start_at = body.start_at ?? body.start;
  const end_at = body.end_at ?? body.end;
  if (!title) return { error: 'Title is required' };
  if (!isValidDate(start_at) || !isValidDate(end_at)) return { error: 'Valid start_at and end_at are required' };
  if (new Date(end_at).getTime() <= new Date(start_at).getTime()) return { error: 'end_at must be after start_at' };
  return { title, start_at: new Date(start_at).toISOString(), end_at: new Date(end_at).toISOString() };
}

function rowToEvent(row) {
  return {
    id: row.id,
    title: row.title,
    start_at: new Date(row.start_at).toISOString(),
    end_at: new Date(row.end_at).toISOString(),
  };
}

app.get('/api/health', (req, res) => res.json({ ok: true }));

app.get('/api/events', async (req, res) => {
  try {
    const { start, end } = req.query;
    if (!isValidDate(start) || !isValidDate(end) || new Date(end) <= new Date(start)) {
      return res.status(400).json({ error: 'Valid start and end query parameters are required' });
    }
    const result = await db.query(
      `SELECT id, title, start_at, end_at
       FROM events
       WHERE start_at < $2::timestamp AND end_at > $1::timestamp
       ORDER BY start_at ASC, end_at ASC, id ASC`,
      [new Date(start).toISOString(), new Date(end).toISOString()]
    );
    res.json(result.rows.map(rowToEvent));
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to fetch events' });
  }
});

app.post('/api/events', async (req, res) => {
  try {
    const valid = validateEventPayload(req.body || {});
    if (valid.error) return res.status(400).json({ error: valid.error });
    const result = await db.query(
      `INSERT INTO events (title, start_at, end_at)
       VALUES ($1, $2::timestamp, $3::timestamp)
       RETURNING id, title, start_at, end_at`,
      [valid.title, valid.start_at, valid.end_at]
    );
    res.status(201).json(rowToEvent(result.rows[0]));
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to create event' });
  }
});

app.put('/api/events/:id', async (req, res) => {
  try {
    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) return res.status(400).json({ error: 'Invalid id' });
    const valid = validateEventPayload(req.body || {});
    if (valid.error) return res.status(400).json({ error: valid.error });
    const result = await db.query(
      `UPDATE events
       SET title = $1, start_at = $2::timestamp, end_at = $3::timestamp
       WHERE id = $4
       RETURNING id, title, start_at, end_at`,
      [valid.title, valid.start_at, valid.end_at, id]
    );
    if (result.rows.length === 0) return res.status(404).json({ error: 'Event not found' });
    res.json(rowToEvent(result.rows[0]));
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to update event' });
  }
});

app.delete('/api/events/:id', async (req, res) => {
  try {
    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) return res.status(400).json({ error: 'Invalid id' });
    const result = await db.query('DELETE FROM events WHERE id = $1 RETURNING id', [id]);
    if (result.rows.length === 0) return res.status(404).json({ error: 'Event not found' });
    res.status(204).end();
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to delete event' });
  }
});

app.listen(PORT, () => {
  console.log(`Calendar API listening on http://localhost:${PORT}`);
});
"}

{"path": "src/main.js", "content": "import './styles.css';

const API_BASE = 'http://localhost:3000/api';
const HOUR_HEIGHT = 64;
const DAY_HEIGHT = HOUR_HEIGHT * 24;
const SNAP_MINUTES = 15;
const DAY_NAMES = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

const app = document.querySelector('#app');
app.innerHTML = `
  <header class="toolbar">
    <div class="brand">
      <h1>Week Calendar</h1>
      <p>Minute-precision week view</p>
    </div>
    <nav class="nav-actions">
      <button id="prevWeek" type="button">← Previous</button>
      <button id="today" type="button">Today</button>
      <button id="nextWeek" type="button">Next →</button>
    </nav>
    <div id="rangeLabel" class="range-label"></div>
  </header>
  <main class="calendar-shell">
    <div class="calendar-header">
      <div class="time-gutter header-gutter"></div>
      <div id="dayHeaders" class="day-headers"></div>
    </div>
    <div class="calendar-scroll">
      <div class="time-gutter" id="timeGutter"></div>
      <div id="weekGrid" class="week-grid"></div>
    </div>
  </main>

  <div id="modalBackdrop" class="modal-backdrop hidden">
    <form id="eventForm" class="event-form">
      <h2 id="formTitle">New event</h2>
      <label>
        Title
        <input id="eventTitle" name="title" type="text" required maxlength="120" />
      </label>
      <div class="form-row">
        <label>
          Start
          <input id="eventStart" name="start" type="datetime-local" required />
        </label>
        <label>
          End
          <input id="eventEnd" name="end" type="datetime-local" required />
        </label>
      </div>
      <p id="formError" class="form-error" role="alert"></p>
      <div class="form-actions">
        <button id="deleteEvent" class="danger hidden" type="button">Delete</button>
        <span class="spacer"></span>
        <button id="cancelForm" type="button">Cancel</button>
        <button class="primary" type="submit">Save</button>
      </div>
    </form>
  </div>
`;

let weekStart = startOfWeek(new Date());
let events = [];
let editingEvent = null;
let dragState = null;

const els = {
  prevWeek: document.querySelector('#prevWeek'),
  today: document.querySelector('#today'),
  nextWeek: document.querySelector('#nextWeek'),
  rangeLabel: document.querySelector('#rangeLabel'),
  dayHeaders: document.querySelector('#dayHeaders'),
  timeGutter: document.querySelector('#timeGutter'),
  weekGrid: document.querySelector('#weekGrid'),
  modalBackdrop: document.querySelector('#modalBackdrop'),
  eventForm: document.querySelector('#eventForm'),
  formTitle: document.querySelector('#formTitle'),
  eventTitle: document.querySelector('#eventTitle'),
  eventStart: document.querySelector('#eventStart'),
  eventEnd: document.querySelector('#eventEnd'),
  formError: document.querySelector('#formError'),
  deleteEvent: document.querySelector('#deleteEvent'),
  cancelForm: document.querySelector('#cancelForm'),
};

initStaticGrid();
attachHandlers();
loadWeek();

function initStaticGrid() {
  els.timeGutter.innerHTML = '';
  for (let h = 0; h <= 24; h++) {
    const label = document.createElement('div');
    label.className = 'time-label';
    label.style.top = `${h * HOUR_HEIGHT}px`;
    label.textContent = `${String(h).padStart(2, '0')}:00`;
    els.timeGutter.appendChild(label);
  }
}

function attachHandlers() {
  els.prevWeek.addEventListener('click', () => changeWeek(-7));
  els.nextWeek.addEventListener('click', () => changeWeek(7));
  els.today.addEventListener('click', () => { weekStart = startOfWeek(new Date()); loadWeek(); });
  els.cancelForm.addEventListener('click', closeModal);
  els.modalBackdrop.addEventListener('mousedown', (e) => { if (e.target === els.modalBackdrop) closeModal(); });
  els.eventForm.addEventListener('submit', saveEvent);
  els.deleteEvent.addEventListener('click', deleteCurrentEvent);
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') closeModal(); });
}

async function loadWeek() {
  renderHeaders();
  try {
    const start = weekStart.toISOString();
    const end = addDays(weekStart, 7).toISOString();
    const res = await fetch(`${API_BASE}/events?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}`);
    if (!res.ok) throw new Error('Failed to load events');
    events = await res.json();
    renderWeekGrid();
  } catch (err) {
    console.error(err);
    events = [];
    renderWeekGrid('Could not load events. Is the API server running?');
  }
}

function renderHeaders() {
  const end = addDays(weekStart, 6);
  els.rangeLabel.textContent = `${formatMonthDay(weekStart)} – ${formatMonthDay(end)} ${end.getFullYear()}`;
  els.dayHeaders.innerHTML = '';
  const todayKey = dateKey(new Date());
  for (let i = 0; i < 7; i++) {
    const d = addDays(weekStart, i);
    const header = document.createElement('div');
    header.className = `day-header ${dateKey(d) === todayKey ? 'today' : ''}`;
    header.innerHTML = `<span>${DAY_NAMES[i]}</span><strong>${d.getDate()}</strong>`;
    els.dayHeaders.appendChild(header);
  }
}

function renderWeekGrid(errorMessage = '') {
  els.weekGrid.innerHTML = '';
  els.weekGrid.style.height = `${DAY_HEIGHT}px`;
  for (let i = 0; i < 7; i++) {
    const day = addDays(weekStart, i);
    const col = document.createElement('section');
    col.className = `day-column ${dateKey(day) === dateKey(new Date()) ? 'today' : ''}`;
    col.dataset.dayIndex = String(i);
    col.style.height = `${DAY_HEIGHT}px`;
    for (let h = 0; h <= 24; h++) {
      const line = document.createElement('div');
      line.className = h === 24 ? 'hour-line last' : 'hour-line';
      line.style.top = `${h * HOUR_HEIGHT}px`;
      col.appendChild(line);
    }
    setupSelectionHandlers(col, day);
    els.weekGrid.appendChild(col);
  }

  if (errorMessage) {
    const msg = document.createElement('div');
    msg.className = 'grid-message';
    msg.textContent = errorMessage;
    els.weekGrid.appendChild(msg);
    return;
  }

  const byDay = splitAndGroupEventsByDay(events);
  byDay.forEach((dayEvents, dayIndex) => {
    const col = els.weekGrid.querySelector(`[data-day-index="${dayIndex}"]`);
    layoutDayEvents(dayEvents).forEach((item) => {
      const el = document.createElement('button');
      el.type = 'button';
      el.className = 'event-block';
      el.style.top = `${item.top}px`;
      el.style.height = `${item.height}px`;
      el.style.left = `calc(${item.leftPct}% + 3px)`;
      el.style.width = `calc(${item.widthPct}% - 6px)`;
      el.innerHTML = `<strong title="${escapeHtml(item.event.title)}">${escapeHtml(item.event.title)}</strong><span>${formatTime(item.visibleStart)}–${formatTime(item.visibleEnd)}</span>`;
      el.addEventListener('click', (e) => {
        e.stopPropagation();
        openEditForm(item.event);
      });
      col.appendChild(el);
    });
  });
}

function splitAndGroupEventsByDay(rawEvents) {
  const days = Array.from({ length: 7 }, () => []);
  const weekEnd = addDays(weekStart, 7);
  rawEvents.forEach((event) => {
    const originalStart = new Date(event.start_at);
    const originalEnd = new Date(event.end_at);
    for (let i = 0; i < 7; i++) {
      const dayStart = addDays(weekStart, i);
      const dayEnd = addDays(dayStart, 1);
      const visibleStart = maxDate(originalStart, dayStart);
      const visibleEnd = minDate(originalEnd, dayEnd, weekEnd);
      if (visibleStart < visibleEnd) {
        days[i].push({ event, visibleStart, visibleEnd });
      }
    }
  });
  return days;
}

function layoutDayEvents(dayEvents) {
  const sorted = [...dayEvents].sort((a, b) => a.visibleStart - b.visibleStart || a.visibleEnd - b.visibleEnd || a.event.id - b.event.id);
  const clusters = [];
  let current = [];
  let clusterEnd = null;

  sorted.forEach((item) => {
    if (current.length === 0 || item.visibleStart < clusterEnd) {
      current.push(item);
      clusterEnd = clusterEnd ? maxDate(clusterEnd, item.visibleEnd) : item.visibleEnd;
    } else {
      clusters.push(current);
      current = [item];
      clusterEnd = item.visibleEnd;
    }
  });
  if (current.length) clusters.push(current);

  const laidOut = [];
  clusters.forEach((cluster) => {
    const columns = [];
    const placements = [];
    cluster.forEach((item) => {
      let colIndex = columns.findIndex((end) => end <= item.visibleStart);
      if (colIndex === -1) {
        colIndex = columns.length;
        columns.push(item.visibleEnd);
      } else {
        columns[colIndex] = item.visibleEnd;
      }
      placements.push({ item, colIndex });
    });
    const colCount = Math.max(columns.length, 1);
    placements.forEach(({ item, colIndex }) => {
      const startMin = minutesSinceMidnight(item.visibleStart);
      const endMin = minutesSinceMidnight(item.visibleEnd);
      laidOut.push({
        ...item,
        top: (startMin / 60) * HOUR_HEIGHT,
        height: Math.max(1, ((endMin - startMin) / 60) * HOUR_HEIGHT),
        leftPct: (colIndex / colCount) * 100,
        widthPct: 100 / colCount,
      });
    });
  });
  return laidOut;
}

function setupSelectionHandlers(col, day) {
  col.addEventListener('mousedown', (e) => {
    if (e.button !== 0 || e.target.closest('.event-block')) return;
    const rect = col.getBoundingClientRect();
    const startY = clamp(e.clientY - rect.top, 0, DAY_HEIGHT);
    const preview = document.createElement('div');
    preview.className = 'selection-preview';
    preview.style.top = `${startY}px`;
    preview.style.height = '1px';
    col.appendChild(preview);
    dragState = { col, day, rect, startY, currentY: startY, preview, moved: false };
    e.preventDefault();
  });

  col.addEventListener('click', (e) => {
    if (e.target.closest('.event-block') || dragState) return;
    const rect = col.getBoundingClientRect();
    const y = clamp(e.clientY - rect.top, 0, DAY_HEIGHT - 1);
    const startMin = snapMinutes((y / DAY_HEIGHT) * 1440);
    openCreateForm(dateAtMinutes(day, startMin), dateAtMinutes(day, Math.min(startMin + 60, 1440)));
  });
}

document.addEventListener('mousemove', (e) => {
  if (!dragState) return;
  const y = clamp(e.clientY - dragState.rect.top, 0, DAY_HEIGHT);
  dragState.currentY = y;
  if (Math.abs(y - dragState.startY) > 3) dragState.moved = true;
  const top = Math.min(dragState.startY, y);
  const height = Math.max(1, Math.abs(y - dragState.startY));
  dragState.preview.style.top = `${top}px`;
  dragState.preview.style.height = `${height}px`;
});

document.addEventListener('mouseup', () => {
  if (!dragState) return;
  const state = dragState;
  dragState = null;
  state.preview.remove();
  if (!state.moved) return;
  let a = snapMinutes((Math.min(state.startY, state.currentY) / DAY_HEIGHT) * 1440);
  let b = snapMinutes((Math.max(state.startY, state.currentY) / DAY_HEIGHT) * 1440);
  if (b <= a) b = Math.min(a + SNAP_MINUTES, 1440);
  openCreateForm(dateAtMinutes(state.day, a), dateAtMinutes(state.day, b));
});

function openCreateForm(start, end) {
  editingEvent = null;
  els.formTitle.textContent = 'New event';
  els.eventTitle.value = '';
  els.eventStart.value = toDatetimeLocalValue(start);
  els.eventEnd.value = toDatetimeLocalValue(end);
  els.deleteEvent.classList.add('hidden');
  els.formError.textContent = '';
  els.modalBackdrop.classList.remove('hidden');
  els.eventTitle.focus();
}

function openEditForm(event) {
  editingEvent = event;
  els.formTitle.textContent = 'Edit event';
  els.eventTitle.value = event.title;
  els.eventStart.value = toDatetimeLocalValue(new Date(event.start_at));
  els.eventEnd.value = toDatetimeLocalValue(new Date(event.end_at));
  els.deleteEvent.classList.remove('hidden');
  els.formError.textContent = '';
  els.modalBackdrop.classList.remove('hidden');
  els.eventTitle.focus();
}

function closeModal() {
  els.modalBackdrop.classList.add('hidden');
  editingEvent = null;
}

async function saveEvent(e) {
  e.preventDefault();
  els.formError.textContent = '';
  const payload = {
    title: els.eventTitle.value.trim(),
    start_at: new Date(els.eventStart.value).toISOString(),
    end_at: new Date(els.eventEnd.value).toISOString(),
  };
  if (!payload.title) return (els.formError.textContent = 'Title is required.');
  if (new Date(payload.end_at) <= new Date(payload.start_at)) return (els.formError.textContent = 'End must be after start.');
  try {
    const url = editingEvent ? `${API_BASE}/events/${editingEvent.id}` : `${API_BASE}/events`;
    const method = editingEvent ? 'PUT' : 'POST';
    const res = await fetch(url, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      throw new Error(err.error || 'Save failed');
    }
    closeModal();
    await loadWeek();
  } catch (err) {
    els.formError.textContent = err.message;
  }
}

async function deleteCurrentEvent() {
  if (!editingEvent) return;
  if (!confirm('Delete this event?')) return;
  try {
    const res = await fetch(`${API_BASE}/events/${editingEvent.id}`, { method: 'DELETE' });
    if (!res.ok) throw new Error('Delete failed');
    closeModal();
    await loadWeek();
  } catch (err) {
    els.formError.textContent = err.message;
  }
}

function changeWeek(days) {
  weekStart = addDays(weekStart, days);
  loadWeek();
}

function startOfWeek(date) {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  const day = d.getDay();
  const diff = (day + 6) % 7;
  d.setDate(d.getDate() - diff);
  return d;
}

function addDays(date, days) {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

function dateAtMinutes(day, minutes) {
  const d = new Date(day);
  d.setHours(0, 0, 0, 0);
  d.setMinutes(minutes);
  return d;
}

function minutesSinceMidnight(date) {
  return date.getHours() * 60 + date.getMinutes() + date.getSeconds() / 60 + date.getMilliseconds() / 60000;
}

function snapMinutes(minutes) {
  return clamp(Math.round(minutes / SNAP_MINUTES) * SNAP_MINUTES, 0, 1440);
}

function toDatetimeLocalValue(date) {
  const d = new Date(date);
  const pad = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function formatTime(date) {
  return `${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
}

function formatMonthDay(date) {
  return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
}

function dateKey(date) {
  const d = new Date(date);
  return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
}

function minDate(...dates) {
  return new Date(Math.min(...dates.map((d) => new Date(d).getTime())));
}

function maxDate(...dates) {
  return new Date(Math.max(...dates.map((d) => new Date(d).getTime())));
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function escapeHtml(value) {
  return String(value).replace(/[&<>'"]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[ch]));
}
"}

{"path": "src/styles.css", "content": ":root {
  --gutter-width: 72px;
  --header-height: 72px;
  --hour-height: 64px;
  --grid-border: #d8dee8;
  --grid-soft: #eef2f7;
  --text: #152238;
  --muted: #687589;
  --blue: #2563eb;
  --blue-dark: #1749b7;
  --today: #eff6ff;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--text);
  background: #f7f9fc;
}

* { box-sizing: border-box; }
html, body, #app { margin: 0; min-height: 100%; }
button, input { font: inherit; }

.toolbar {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 18px 24px;
  background: #ffffff;
  border-bottom: 1px solid var(--grid-border);
  position: sticky;
  top: 0;
  z-index: 20;
}

.brand { margin-right: auto; }
.brand h1 { margin: 0; font-size: 22px; line-height: 1.1; }
.brand p { margin: 3px 0 0; color: var(--muted); font-size: 13px; }
.nav-actions { display: flex; gap: 8px; }
.nav-actions button,
.form-actions button {
  border: 1px solid var(--grid-border);
  background: #fff;
  border-radius: 9px;
  padding: 8px 12px;
  cursor: pointer;
  color: var(--text);
}
.nav-actions button:hover,
.form-actions button:hover { background: #f2f5f9; }
.range-label { min-width: 190px; text-align: right; color: var(--muted); font-weight: 600; }

.calendar-shell {
  margin: 18px 24px 28px;
  border: 1px solid var(--grid-border);
  border-radius: 14px;
  overflow: hidden;
  background: white;
  box-shadow: 0 12px 32px rgba(21, 34, 56, 0.08);
}

.calendar-header {
  display: grid;
  grid-template-columns: var(--gutter-width) 1fr;
  height: var(--header-height);
  border-bottom: 1px solid var(--grid-border);
  background: #fff;
  position: sticky;
  top: 79px;
  z-index: 10;
}
.header-gutter { border-right: 1px solid var(--grid-border); }
.day-headers,
.week-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(120px, 1fr));
}
.day-header {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 4px;
  border-right: 1px solid var(--grid-border);
  color: var(--muted);
}
.day-header:last-child { border-right: 0; }
.day-header strong {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  font-size: 18px;
  color: var(--text);
}
.day-header.today { background: var(--today); color: var(--blue); }
.day-header.today strong { background: var(--blue); color: white; }

.calendar-scroll {
  display: grid;
  grid-template-columns: var(--gutter-width) minmax(840px, 1fr);
  max-height: calc(100vh - 174px);
  overflow: auto;
}
.time-gutter {
  position: relative;
  height: calc(var(--hour-height) * 24);
  background: #fbfcfe;
  border-right: 1px solid var(--grid-border);
  flex: none;
}
.time-label {
  position: absolute;
  right: 10px;
  transform: translateY(-50%);
  color: var(--muted);
  font-size: 12px;
  line-height: 1;
  white-space: nowrap;
}
.time-label:first-child { transform: translateY(0); top: 0 !important; }
.time-label:last-child { transform: translateY(-100%); }

.week-grid { position: relative; min-width: 840px; }
.day-column {
  position: relative;
  min-width: 0;
  border-right: 1px solid var(--grid-border);
  background: #fff;
  cursor: crosshair;
  overflow: hidden;
}
.day-column:last-child { border-right: 0; }
.day-column.today { background: linear-gradient(var(--today), var(--today)), #fff; }
.hour-line {
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--grid-soft);
  pointer-events: none;
}
.hour-line:nth-child(6n + 1) { background: var(--grid-border); }
.hour-line.last { bottom: 0; top: auto !important; background: var(--grid-border); }

.event-block {
  position: absolute;
  z-index: 3;
  border: 1px solid rgba(23, 73, 183, 0.34);
  border-left: 4px solid var(--blue-dark);
  border-radius: 8px;
  background: linear-gradient(135deg, #3b82f6, #2563eb);
  color: white;
  padding: 5px 6px;
  text-align: left;
  overflow: hidden;
  cursor: pointer;
  box-shadow: 0 4px 10px rgba(37, 99, 235, 0.20);
  min-width: 0;
}
.event-block:hover,
.event-block:focus { z-index: 5; filter: brightness(1.04); outline: 2px solid rgba(37, 99, 235, 0.28); }
.event-block strong,
.event-block span {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}
.event-block strong { font-size: 13px; line-height: 1.2; }
.event-block span { font-size: 11px; opacity: 0.92; margin-top: 2px; }

.selection-preview {
  position: absolute;
  left: 4px;
  right: 4px;
  z-index: 2;
  background: rgba(37, 99, 235, 0.16);
  border: 1px dashed var(--blue);
  border-radius: 8px;
  pointer-events: none;
}
.grid-message {
  position: absolute;
  top: 24px;
  left: 24px;
  right: 24px;
  padding: 14px 16px;
  background: #fff7ed;
  border: 1px solid #fed7aa;
  color: #9a3412;
  border-radius: 10px;
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  background: rgba(15, 23, 42, 0.42);
  padding: 20px;
}
.hidden { display: none !important; }
.event-form {
  width: min(560px, 100%);
  background: #fff;
  border-radius: 16px;
  box-shadow: 0 28px 70px rgba(15, 23, 42, 0.26);
  padding: 22px;
}
.event-form h2 { margin: 0 0 18px; }
.event-form label {
  display: flex;
  flex-direction: column;
  gap: 7px;
  color: var(--muted);
  font-size: 13px;
  font-weight: 700;
}
.event-form input {
  color: var(--text);
  border: 1px solid var(--grid-border);
  border-radius: 10px;
  padding: 10px 12px;
  outline: none;
}
.event-form input:focus { border-color: var(--blue); box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.13); }
.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 14px;
}
.form-error { min-height: 20px; margin: 10px 0 0; color: #dc2626; font-size: 13px; }
.form-actions { display: flex; gap: 8px; align-items: center; margin-top: 10px; }
.form-actions .spacer { flex: 1; }
.form-actions .primary { background: var(--blue); border-color: var(--blue); color: white; }
.form-actions .primary:hover { background: var(--blue-dark); }
.form-actions .danger { background: #fee2e2; border-color: #fecaca; color: #b91c1c; margin-right: auto; }
.form-actions .danger:hover { background: #fecaca; }

@media (max-width: 760px) {
  .toolbar { align-items: flex-start; flex-direction: column; gap: 12px; }
  .brand { margin-right: 0; }
  .range-label { text-align: left; }
  .calendar-shell { margin: 10px; }
  .calendar-header { top: 0; }
  .form-row { grid-template-columns: 1fr; }
}
"}

{"path": "server.js", "content": "import express from 'express';
import cors from 'cors';
import { PGlite } from '@electric-sql/pglite';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const PORT = process.env.PORT || 3000;

const app = express();
app.use(cors());
app.use(express.json());

const db = new PGlite(path.join(__dirname, 'pgdata'));

await db.query(`
  CREATE TABLE IF NOT EXISTS events (
    id SERIAL PRIMARY KEY,
    title TEXT NOT NULL,
    start_at TIMESTAMP NOT NULL,
    end_at TIMESTAMP NOT NULL,
    CONSTRAINT valid_event_time CHECK (end_at > start_at)
  );
`);

function isValidDate(value) {
  const d = new Date(value);
  return value && !Number.isNaN(d.getTime());
}

function validateEventPayload(body) {
  const title = typeof body.title === 'string' ? body.title.trim() : '';
  const start_at = body.start_at ?? body.start;
  const end_at = body.end_at ?? body.end;
  if (!title) return { error: 'Title is required' };
  if (!isValidDate(start_at) || !isValidDate(end_at)) return { error: 'Valid start_at and end_at are required' };
  if (new Date(end_at).getTime() <= new Date(start_at).getTime()) return { error: 'end_at must be after start_at' };
  return { title, start_at: new Date(start_at).toISOString(), end_at: new Date(end_at).toISOString() };
}

function rowToEvent(row) {
  return {
    id: row.id,
    title: row.title,
    start_at: new Date(row.start_at).toISOString(),
    end_at: new Date(row.end_at).toISOString(),
  };
}

app.get('/api/health', (req, res) => res.json({ ok: true }));

app.get('/api/events', async (req, res) => {
  try {
    const { start, end } = req.query;
    if (!isValidDate(start) || !isValidDate(end) || new Date(end) <= new Date(start)) {
      return res.status(400).json({ error: 'Valid start and end query parameters are required' });
    }
    const result = await db.query(
      `SELECT id, title, start_at, end_at
       FROM events
       WHERE start_at < $2::timestamp AND end_at > $1::timestamp
       ORDER BY start_at ASC, end_at ASC, id ASC`,
      [new Date(start).toISOString(), new Date(end).toISOString()]
    );
    res.json(result.rows.map(rowToEvent));
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to fetch events' });
  }
});

app.post('/api/events', async (req, res) => {
  try {
    const valid = validateEventPayload(req.body || {});
    if (valid.error) return res.status(400).json({ error: valid.error });
    const result = await db.query(
      `INSERT INTO events (title, start_at, end_at)
       VALUES ($1, $2::timestamp, $3::timestamp)
       RETURNING id, title, start_at, end_at`,
      [valid.title, valid.start_at, valid.end_at]
    );
    res.status(201).json(rowToEvent(result.rows[0]));
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to create event' });
  }
});

app.put('/api/events/:id', async (req, res) => {
  try {
    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) return res.status(400).json({ error: 'Invalid id' });
    const valid = validateEventPayload(req.body || {});
    if (valid.error) return res.status(400).json({ error: valid.error });
    const result = await db.query(
      `UPDATE events
       SET title = $1, start_at = $2::timestamp, end_at = $3::timestamp
       WHERE id = $4
       RETURNING id, title, start_at, end_at`,
      [valid.title, valid.start_at, valid.end_at, id]
    );
    if (result.rows.length === 0) return res.status(404).json({ error: 'Event not found' });
    res.json(rowToEvent(result.rows[0]));
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to update event' });
  }
});

app.delete('/api/events/:id', async (req, res) => {
  try {
    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) return res.status(400).json({ error: 'Invalid id' });
    const result = await db.query('DELETE FROM events WHERE id = $1 RETURNING id', [id]);
    if (result.rows.length === 0) return res.status(404).json({ error: 'Event not found' });
    res.status(204).end();
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to delete event' });
  }
});

app.listen(PORT, () => {
  console.log(`Calendar API listening on http://localhost:${PORT}`);
});
"}

{"path": "src/main.js", "content": "import './styles.css';

const API_BASE = 'http://localhost:3000/api';
const HOUR_HEIGHT = 64;
const DAY_HEIGHT = HOUR_HEIGHT * 24;
const SNAP_MINUTES = 15;
const DAY_NAMES = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

const app = document.querySelector('#app');
app.innerHTML = `
  <header class="toolbar">
    <div class="brand">
      <h1>Week Calendar</h1>
      <p>Minute-precision week view</p>
    </div>
    <nav class="nav-actions">
      <button id="prevWeek" type="button">← Previous</button>
      <button id="today" type="button">Today</button>
      <button id="nextWeek" type="button">Next →</button>
    </nav>
    <div id="rangeLabel" class="range-label"></div>
  </header>
  <main class="calendar-shell">
    <div class="calendar-header">
      <div class="time-gutter header-gutter"></div>
      <div id="dayHeaders" class="day-headers"></div>
    </div>
    <div class="calendar-scroll">
      <div class="time-gutter" id="timeGutter"></div>
      <div id="weekGrid" class="week-grid"></div>
    </div>
  </main>

  <div id="modalBackdrop" class="modal-backdrop hidden">
    <form id="eventForm" class="event-form">
      <h2 id="formTitle">New event</h2>
      <label>
        Title
        <input id="eventTitle" name="title" type="text" required maxlength="120" />
      </label>
      <div class="form-row">
        <label>
          Start
          <input id="eventStart" name="start" type="datetime-local" required />
        </label>
        <label>
          End
          <input id="eventEnd" name="end" type="datetime-local" required />
        </label>
      </div>
      <p id="formError" class="form-error" role="alert"></p>
      <div class="form-actions">
        <button id="deleteEvent" class="danger hidden" type="button">Delete</button>
        <span class="spacer"></span>
        <button id="cancelForm" type="button">Cancel</button>
        <button class="primary" type="submit">Save</button>
      </div>
    </form>
  </div>
`;

let weekStart = startOfWeek(new Date());
let events = [];
let editingEvent = null;
let dragState = null;

const els = {
  prevWeek: document.querySelector('#prevWeek'),
  today: document.querySelector('#today'),
  nextWeek: document.querySelector('#nextWeek'),
  rangeLabel: document.querySelector('#rangeLabel'),
  dayHeaders: document.querySelector('#dayHeaders'),
  timeGutter: document.querySelector('#timeGutter'),
  weekGrid: document.querySelector('#weekGrid'),
  modalBackdrop: document.querySelector('#modalBackdrop'),
  eventForm: document.querySelector('#eventForm'),
  formTitle: document.querySelector('#formTitle'),
  eventTitle: document.querySelector('#eventTitle'),
  eventStart: document.querySelector('#eventStart'),
  eventEnd: document.querySelector('#eventEnd'),
  formError: document.querySelector('#formError'),
  deleteEvent: document.querySelector('#deleteEvent'),
  cancelForm: document.querySelector('#cancelForm'),
};

initStaticGrid();
attachHandlers();
loadWeek();

function initStaticGrid() {
  els.timeGutter.innerHTML = '';
  for (let h = 0; h <= 24; h++) {
    const label = document.createElement('div');
    label.className = 'time-label';
    label.style.top = `${h * HOUR_HEIGHT}px`;
    label.textContent = `${String(h).padStart(2, '0')}:00`;
    els.timeGutter.appendChild(label);
  }
}

function attachHandlers() {
  els.prevWeek.addEventListener('click', () => changeWeek(-7));
  els.nextWeek.addEventListener('click', () => changeWeek(7));
  els.today.addEventListener('click', () => { weekStart = startOfWeek(new Date()); loadWeek(); });
  els.cancelForm.addEventListener('click', closeModal);
  els.modalBackdrop.addEventListener('mousedown', (e) => { if (e.target === els.modalBackdrop) closeModal(); });
  els.eventForm.addEventListener('submit', saveEvent);
  els.deleteEvent.addEventListener('click', deleteCurrentEvent);
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') closeModal(); });
}

async function loadWeek() {
  renderHeaders();
  try {
    const start = weekStart.toISOString();
    const end = addDays(weekStart, 7).toISOString();
    const res = await fetch(`${API_BASE}/events?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}`);
    if (!res.ok) throw new Error('Failed to load events');
    events = await res.json();
    renderWeekGrid();
  } catch (err) {
    console.error(err);
    events = [];
    renderWeekGrid('Could not load events. Is the API server running?');
  }
}

function renderHeaders() {
  const end = addDays(weekStart, 6);
  els.rangeLabel.textContent = `${formatMonthDay(weekStart)} – ${formatMonthDay(end)} ${end.getFullYear()}`;
  els.dayHeaders.innerHTML = '';
  const todayKey = dateKey(new Date());
  for (let i = 0; i < 7; i++) {
    const d = addDays(weekStart, i);
    const header = document.createElement('div');
    header.className = `day-header ${dateKey(d) === todayKey ? 'today' : ''}`;
    header.innerHTML = `<span>${DAY_NAMES[i]}</span><strong>${d.getDate()}</strong>`;
    els.dayHeaders.appendChild(header);
  }
}

function renderWeekGrid(errorMessage = '') {
  els.weekGrid.innerHTML = '';
  els.weekGrid.style.height = `${DAY_HEIGHT}px`;
  for (let i = 0; i < 7; i++) {
    const day = addDays(weekStart, i);
    const col = document.createElement('section');
    col.className = `day-column ${dateKey(day) === dateKey(new Date()) ? 'today' : ''}`;
    col.dataset.dayIndex = String(i);
    col.style.height = `${DAY_HEIGHT}px`;
    for (let h = 0; h <= 24; h++) {
      const line = document.createElement('div');
      line.className = h === 24 ? 'hour-line last' : 'hour-line';
      line.style.top = `${h * HOUR_HEIGHT}px`;
      col.appendChild(line);
    }
    setupSelectionHandlers(col, day);
    els.weekGrid.appendChild(col);
  }

  if (errorMessage) {
    const msg = document.createElement('div');
    msg.className = 'grid-message';
    msg.textContent = errorMessage;
    els.weekGrid.appendChild(msg);
    return;
  }

  const byDay = splitAndGroupEventsByDay(events);
  byDay.forEach((dayEvents, dayIndex) => {
    const col = els.weekGrid.querySelector(`[data-day-index="${dayIndex}"]`);
    layoutDayEvents(dayEvents).forEach((item) => {
      const el = document.createElement('button');
      el.type = 'button';
      el.className = 'event-block';
      el.style.top = `${item.top}px`;
      el.style.height = `${item.height}px`;
      el.style.left = `calc(${item.leftPct}% + 3px)`;
      el.style.width = `calc(${item.widthPct}% - 6px)`;
      el.innerHTML = `<strong title="${escapeHtml(item.event.title)}">${escapeHtml(item.event.title)}</strong><span>${formatTime(item.visibleStart)}–${formatTime(item.visibleEnd)}</span>`;
      el.addEventListener('click', (e) => {
        e.stopPropagation();
        openEditForm(item.event);
      });
      col.appendChild(el);
    });
  });
}

function splitAndGroupEventsByDay(rawEvents) {
  const days = Array.from({ length: 7 }, () => []);
  const weekEnd = addDays(weekStart, 7);
  rawEvents.forEach((event) => {
    const originalStart = new Date(event.start_at);
    const originalEnd = new Date(event.end_at);
    for (let i = 0; i < 7; i++) {
      const dayStart = addDays(weekStart, i);
      const dayEnd = addDays(dayStart, 1);
      const visibleStart = maxDate(originalStart, dayStart);
      const visibleEnd = minDate(originalEnd, dayEnd, weekEnd);
      if (visibleStart < visibleEnd) {
        days[i].push({ event, visibleStart, visibleEnd });
      }
    }
  });
  return days;
}

function layoutDayEvents(dayEvents) {
  const sorted = [...dayEvents].sort((a, b) => a.visibleStart - b.visibleStart || a.visibleEnd - b.visibleEnd || a.event.id - b.event.id);
  const clusters = [];
  let current = [];
  let clusterEnd = null;

  sorted.forEach((item) => {
    if (current.length === 0 || item.visibleStart < clusterEnd) {
      current.push(item);
      clusterEnd = clusterEnd ? maxDate(clusterEnd, item.visibleEnd) : item.visibleEnd;
    } else {
      clusters.push(current);
      current = [item];
      clusterEnd = item.visibleEnd;
    }
  });
  if (current.length) clusters.push(current);

  const laidOut = [];
  clusters.forEach((cluster) => {
    const columns = [];
    const placements = [];
    cluster.forEach((item) => {
      let colIndex = columns.findIndex((end) => end <= item.visibleStart);
      if (colIndex === -1) {
        colIndex = columns.length;
        columns.push(item.visibleEnd);
      } else {
        columns[colIndex] = item.visibleEnd;
      }
      placements.push({ item, colIndex });
    });
    const colCount = Math.max(columns.length, 1);
    placements.forEach(({ item, colIndex }) => {
      const startMin = minutesSinceMidnight(item.visibleStart);
      const endMin = minutesSinceMidnight(item.visibleEnd);
      laidOut.push({
        ...item,
        top: (startMin / 60) * HOUR_HEIGHT,
        height: Math.max(1, ((endMin - startMin) / 60) * HOUR_HEIGHT),
        leftPct: (colIndex / colCount) * 100,
        widthPct: 100 / colCount,
      });
    });
  });
  return laidOut;
}

function setupSelectionHandlers(col, day) {
  col.addEventListener('mousedown', (e) => {
    if (e.button !== 0 || e.target.closest('.event-block')) return;
    const rect = col.getBoundingClientRect();
    const startY = clamp(e.clientY - rect.top, 0, DAY_HEIGHT);
    const preview = document.createElement('div');
    preview.className = 'selection-preview';
    preview.style.top = `${startY}px`;
    preview.style.height = '1px';
    col.appendChild(preview);
    dragState = { col, day, rect, startY, currentY: startY, preview, moved: false };
    e.preventDefault();
  });

  col.addEventListener('click', (e) => {
    if (e.target.closest('.event-block') || dragState) return;
    const rect = col.getBoundingClientRect();
    const y = clamp(e.clientY - rect.top, 0, DAY_HEIGHT - 1);
    const startMin = snapMinutes((y / DAY_HEIGHT) * 1440);
    openCreateForm(dateAtMinutes(day, startMin), dateAtMinutes(day, Math.min(startMin + 60, 1440)));
  });
}

document.addEventListener('mousemove', (e) => {
  if (!dragState) return;
  const y = clamp(e.clientY - dragState.rect.top, 0, DAY_HEIGHT);
  dragState.currentY = y;
  if (Math.abs(y - dragState.startY) > 3) dragState.moved = true;
  const top = Math.min(dragState.startY, y);
  const height = Math.max(1, Math.abs(y - dragState.startY));
  dragState.preview.style.top = `${top}px`;
  dragState.preview.style.height = `${height}px`;
});

document.addEventListener('mouseup', () => {
  if (!dragState) return;
  const state = dragState;
  dragState = null;
  state.preview.remove();
  if (!state.moved) return;
  let a = snapMinutes((Math.min(state.startY, state.currentY) / DAY_HEIGHT) * 1440);
  let b = snapMinutes((Math.max(state.startY, state.currentY) / DAY_HEIGHT) * 1440);
  if (b <= a) b = Math.min(a + SNAP_MINUTES, 1440);
  openCreateForm(dateAtMinutes(state.day, a), dateAtMinutes(state.day, b));
});

function openCreateForm(start, end) {
  editingEvent = null;
  els.formTitle.textContent = 'New event';
  els.eventTitle.value = '';
  els.eventStart.value = toDatetimeLocalValue(start);
  els.eventEnd.value = toDatetimeLocalValue(end);
  els.deleteEvent.classList.add('hidden');
  els.formError.textContent = '';
  els.modalBackdrop.classList.remove('hidden');
  els.eventTitle.focus();
}

function openEditForm(event) {
  editingEvent = event;
  els.formTitle.textContent = 'Edit event';
  els.eventTitle.value = event.title;
  els.eventStart.value = toDatetimeLocalValue(new Date(event.start_at));
  els.eventEnd.value = toDatetimeLocalValue(new Date(event.end_at));
  els.deleteEvent.classList.remove('hidden');
  els.formError.textContent = '';
  els.modalBackdrop.classList.remove('hidden');
  els.eventTitle.focus();
}

function closeModal() {
  els.modalBackdrop.classList.add('hidden');
  editingEvent = null;
}

async function saveEvent(e) {
  e.preventDefault();
  els.formError.textContent = '';
  const payload = {
    title: els.eventTitle.value.trim(),
    start_at: new Date(els.eventStart.value).toISOString(),
    end_at: new Date(els.eventEnd.value).toISOString(),
  };
  if (!payload.title) return (els.formError.textContent = 'Title is required.');
  if (new Date(payload.end_at) <= new Date(payload.start_at)) return (els.formError.textContent = 'End must be after start.');
  try {
    const url = editingEvent ? `${API_BASE}/events/${editingEvent.id}` : `${API_BASE}/events`;
    const method = editingEvent ? 'PUT' : 'POST';
    const res = await fetch(url, { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      throw new Error(err.error || 'Save failed');
    }
    closeModal();
    await loadWeek();
  } catch (err) {
    els.formError.textContent = err.message;
  }
}

async function deleteCurrentEvent() {
  if (!editingEvent) return;
  if (!confirm('Delete this event?')) return;
  try {
    const res = await fetch(`${API_BASE}/events/${editingEvent.id}`, { method: 'DELETE' });
    if (!res.ok) throw new Error('Delete failed');
    closeModal();
    await loadWeek();
  } catch (err) {
    els.formError.textContent = err.message;
  }
}

function changeWeek(days) {
  weekStart = addDays(weekStart, days);
  loadWeek();
}

function startOfWeek(date) {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  const day = d.getDay();
  const diff = (day + 6) % 7;
  d.setDate(d.getDate() - diff);
  return d;
}

function addDays(date, days) {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

function dateAtMinutes(day, minutes) {
  const d = new Date(day);
  d.setHours(0, 0, 0, 0);
  d.setMinutes(minutes);
  return d;
}

function minutesSinceMidnight(date) {
  return date.getHours() * 60 + date.getMinutes() + date.getSeconds() / 60 + date.getMilliseconds() / 60000;
}

function snapMinutes(minutes) {
  return clamp(Math.round(minutes / SNAP_MINUTES) * SNAP_MINUTES, 0, 1440);
}

function toDatetimeLocalValue(date) {
  const d = new Date(date);
  const pad = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function formatTime(date) {
  return `${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
}

function formatMonthDay(date) {
  return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
}

function dateKey(date) {
  const d = new Date(date);
  return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
}

function minDate(...dates) {
  return new Date(Math.min(...dates.map((d) => new Date(d).getTime())));
}

function maxDate(...dates) {
  return new Date(Math.max(...dates.map((d) => new Date(d).getTime())));
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function escapeHtml(value) {
  return String(value).replace(/[&<>'"]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[ch]));
}
"}

{"path": "src/styles.css", "content": ":root {
  --gutter-width: 72px;
  --header-height: 72px;
  --hour-height: 64px;
  --grid-border: #d8dee8;
  --grid-soft: #eef2f7;
  --text: #152238;
  --muted: #687589;
  --blue: #2563eb;
  --blue-dark: #1749b7;
  --today: #eff6ff;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--text);
  background: #f7f9fc;
}

* { box-sizing: border-box; }
html, body, #app { margin: 0; min-height: 100%; }
button, input { font: inherit; }

.toolbar {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 18px 24px;
  background: #ffffff;
  border-bottom: 1px solid var(--grid-border);
  position: sticky;
  top: 0;
  z-index: 20;
}

.brand { margin-right: auto; }
.brand h1 { margin: 0; font-size: 22px; line-height: 1.1; }
.brand p { margin: 3px 0 0; color: var(--muted); font-size: 13px; }
.nav-actions { display: flex; gap: 8px; }
.nav-actions button,
.form-actions button {
  border: 1px solid var(--grid-border);
  background: #fff;
  border-radius: 9px;
  padding: 8px 12px;
  cursor: pointer;
  color: var(--text);
}
.nav-actions button:hover,
.form-actions button:hover { background: #f2f5f9; }
.range-label { min-width: 190px; text-align: right; color: var(--muted); font-weight: 600; }

.calendar-shell {
  margin: 18px 24px 28px;
  border: 1px solid var(--grid-border);
  border-radius: 14px;
  overflow: hidden;
  background: white;
  box-shadow: 0 12px 32px rgba(21, 34, 56, 0.08);
}

.calendar-header {
  display: grid;
  grid-template-columns: var(--gutter-width) 1fr;
  height: var(--header-height);
  border-bottom: 1px solid var(--grid-border);
  background: #fff;
  position: sticky;
  top: 79px;
  z-index: 10;
}
.header-gutter { border-right: 1px solid var(--grid-border); }
.day-headers,
.week-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(120px, 1fr));
}
.day-header {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 4px;
  border-right: 1px solid var(--grid-border);
  color: var(--muted);
}
.day-header:last-child { border-right: 0; }
.day-header strong {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  font-size: 18px;
  color: var(--text);
}
.day-header.today { background: var(--today); color: var(--blue); }
.day-header.today strong { background: var(--blue); color: white; }

.calendar-scroll {
  display: grid;
  grid-template-columns: var(--gutter-width) minmax(840px, 1fr);
  max-height: calc(100vh - 174px);
  overflow: auto;
}
.time-gutter {
  position: relative;
  height: calc(var(--hour-height) * 24);
  background: #fbfcfe;
  border-right: 1px solid var(--grid-border);
  flex: none;
}
.time-label {
  position: absolute;
  right: 10px;
  transform: translateY(-50%);
  color: var(--muted);
  font-size: 12px;
  line-height: 1;
  white-space: nowrap;
}
.time-label:first-child { transform: translateY(0); top: 0 !important; }
.time-label:last-child { transform: translateY(-100%); }

.week-grid { position: relative; min-width: 840px; }
.day-column {
  position: relative;
  min-width: 0;
  border-right: 1px solid var(--grid-border);
  background: #fff;
  cursor: crosshair;
  overflow: hidden;
}
.day-column:last-child { border-right: 0; }
.day-column.today { background: linear-gradient(var(--today), var(--today)), #fff; }
.hour-line {
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--grid-soft);
  pointer-events: none;
}
.hour-line:nth-child(6n + 1) { background: var(--grid-border); }
.hour-line.last { bottom: 0; top: auto !important; background: var(--grid-border); }

.event-block {
  position: absolute;
  z-index: 3;
  border: 1px solid rgba(23, 73, 183, 0.34);
  border-left: 4px solid var(--blue-dark);
  border-radius: 8px;
  background: linear-gradient(135deg, #3b82f6, #2563eb);
  color: white;
  padding: 5px 6px;
  text-align: left;
  overflow: hidden;
  cursor: pointer;
  box-shadow: 0 4px 10px rgba(37, 99, 235, 0.20);
  min-width: 0;
}
.event-block:hover,
.event-block:focus { z-index: 5; filter: brightness(1.04); outline: 2px solid rgba(37, 99, 235, 0.28); }
.event-block strong,
.event-block span {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}
.event-block strong { font-size: 13px; line-height: 1.2; }
.event-block span { font-size: 11px; opacity: 0.92; margin-top: 2px; }

.selection-preview {
  position: absolute;
  left: 4px;
  right: 4px;
  z-index: 2;
  background: rgba(37, 99, 235, 0.16);
  border: 1px dashed var(--blue);
  border-radius: 8px;
  pointer-events: none;
}
.grid-message {
  position: absolute;
  top: 24px;
  left: 24px;
  right: 24px;
  padding: 14px 16px;
  background: #fff7ed;
  border: 1px solid #fed7aa;
  color: #9a3412;
  border-radius: 10px;
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  background: rgba(15, 23, 42, 0.42);
  padding: 20px;
}
.hidden { display: none !important; }
.event-form {
  width: min(560px, 100%);
  background: #fff;
  border-radius: 16px;
  box-shadow: 0 28px 70px rgba(15, 23, 42, 0.26);
  padding: 22px;
}
.event-form h2 { margin: 0 0 18px; }
.event-form label {
  display: flex;
  flex-direction: column;
  gap: 7px;
  color: var(--muted);
  font-size: 13px;
  font-weight: 700;
}
.event-form input {
  color: var(--text);
  border: 1px solid var(--grid-border);
  border-radius: 10px;
  padding: 10px 12px;
  outline: none;
}
.event-form input:focus { border-color: var(--blue); box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.13); }
.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 14px;
}
.form-error { min-height: 20px; margin: 10px 0 0; color: #dc2626; font-size: 13px; }
.form-actions { display: flex; gap: 8px; align-items: center; margin-top: 10px; }
.form-actions .spacer { flex: 1; }
.form-actions .primary { background: var(--blue); border-color: var(--blue); color: white; }
.form-actions .primary:hover { background: var(--blue-dark); }
.form-actions .danger { background: #fee2e2; border-color: #fecaca; color: #b91c1c; margin-right: auto; }
.form-actions .danger:hover { background: #fecaca; }

@media (max-width: 760px) {
  .toolbar { align-items: flex-start; flex-direction: column; gap: 12px; }
  .brand { margin-right: 0; }
  .range-label { text-align: left; }
  .calendar-shell { margin: 10px; }
  .calendar-header { top: 0; }
  .form-row { grid-template-columns: 1fr; }
}
"}

